import type { Locale } from '@/i18n/types';
import type { Flashcard } from './flashcards';
import { DRILL_EN } from './flashcard-i18n-drill';
import { SCENARIO_EN } from './flashcard-i18n-scenario';

/**
 * 闪卡英文覆盖层：中文是基底，这里按卡片 id 提供英文的 front/back；
 * 缺失的条目自动回退中文基底（与 i18n/content/{en,es} 同一思路）。
 */
export const FLASHCARD_EN: Record<string, { front: string; back: string; src: string }> = {
  'amc10-0001': { front: 'What is the order of operations?', back: 'Parentheses, then exponents and roots, then multiply and divide, then add and subtract; within one level work left to right.', src: '41e67516fdeb' },
  'amc10-0002': { front: 'What is the distributive law?', back: 'a(b+c)=ab+ac; read backwards it pulls out a common factor.', src: 'c3ea4fa9595a' },
  'amc10-0003': { front: 'What is the difference of squares?', back: 'a²-b²=(a-b)(a+b).', src: 'fa8f6a4174d3' },
  'amc10-0004': { front: 'What is the perfect square identity?', back: '(a±b)²=a²±2ab+b².', src: 'a5558d2ad648' },
  'amc10-0005': { front: 'What does the absolute value |x| mean?', back: 'The distance from x to 0, so it is never negative.', src: '482bb80a3e73' },
  'amc10-0006': { front: 'What is the standard form of scientific notation?', back: 'a×10^n where 1≤|a|<10 and n is an integer.', src: '54b6e1bd8d02' },
  'amc10-0007': { front: 'How do you cross-multiply the proportion a/b=c/d?', back: 'When the denominators are nonzero you get ad=bc.', src: 'e29add37bbd0' },
  'amc10-0008': { front: 'What are the direct and inverse variation models?', back: 'Direct: y=kx. Inverse: y=k/x, or xy=k. Both need k≠0, and the inverse form also needs x≠0.', src: '67a91e2ea563' },
  'amc10-0009': { front: 'Can two successive percentage changes be added directly?', back: 'Usually not; the overall factor is the product of the individual factors.', src: '7722e489b4f1' },
  'amc10-0010': { front: 'What are the multipliers for an r% increase and an r% decrease?', back: '1+r/100 and 1-r/100 respectively.', src: '63bc7f8f7269' },
  'amc10-0011': { front: 'If a value rises r% and then falls r%, does it return to where it started?', back: 'No; the overall factor is 1-(r/100)².', src: '9d54e6be6b7f' },
  'amc10-0012': { front: 'What is the weighted average formula?', back: 'Weighted sum divided by the total weight.', src: 'bdb60c8a2504' },
  'amc10-0013': { front: 'How do you recover a total from an average?', back: 'Total = average × number of data points.', src: '28a813fe3df3' },
  'amc10-0014': { front: 'How do you combine the averages of two data sets?', back: '(n₁a₁+n₂a₂)/(n₁+n₂).', src: '20f561132391' },
  'amc10-0015': { front: 'A round trip at speeds u and v: what is the average speed?', back: '2uv/(u+v), which is not the arithmetic mean.', src: '0d75affe77ff' },
  'amc10-0016': { front: 'What relates distance, speed and time?', back: 'd=rt; convert everything to consistent units before writing the equation.', src: 'acaa4425223d' },
  'amc10-0017': { front: 'What is the relative speed when two objects move toward each other?', back: 'The sum of the two speeds.', src: 'f04b1c99dc1b' },
  'amc10-0018': { front: 'What is the relative speed in a same-direction chase?', back: 'The faster speed minus the slower speed.', src: 'cee7aa2037ac' },
  'amc10-0019': { front: 'What is the work-rate model?', back: 'Work = rate × time; when two workers work together their rates add.', src: 'b837329145bc' },
  'amc10-0020': { front: 'What is conserved in a mixture problem?', back: 'The amount of solute; concentration = solute / total mixture.', src: 'b2b721fee1c0' },
  'amc10-0021': { front: 'If a figure is scaled by k, how do length, area and volume change?', back: 'They multiply by k, k² and k³ respectively.', src: '119a7d26d27c' },
  'amc10-0022': { front: 'What is a dimensional check good for?', back: 'Checking that quantities being added share units and that the answer carries a sensible unit.', src: '46b9e1b19e3f' },
  'amc10-0023': { front: 'What is the basic principle of bounding an estimate?', back: 'For positive quantities choose bounds in the direction of the operation, then check the direction of the error at the end.', src: '3d80d16e1187' },
  'amc10-0024': { front: 'What is the harmonic mean formula?', back: 'For positive x₁,…,x_n the harmonic mean is n/(Σ1/x_i).', src: 'a9ae0cd59bbf' },
  'amc10-0025': { front: 'What does a|b mean?', back: 'There is an integer k such that b=ak.', src: 'd26b48121a80' },
  'amc10-0026': { front: 'What is the definition of a prime number?', back: 'An integer greater than 1 whose only positive divisors are 1 and itself; 1 is not prime.', src: '103bfef5c457' },
  'amc10-0027': { front: 'What does the fundamental theorem of arithmetic say?', back: 'Every integer greater than 1 factors uniquely into a product of prime powers, ignoring order.', src: 'dacf66ab8b34' },
  'amc10-0028': { front: 'What is gcd(a,b)?', back: 'The largest positive integer that divides both a and b.', src: 'cc731f6cc669' },
  'amc10-0029': { front: 'What is lcm(a,b)?', back: 'The smallest positive integer divisible by both a and b.', src: '4dea5aeb45eb' },
  'amc10-0030': { front: 'How are gcd and lcm related by multiplication?', back: 'For positive integers, gcd(a,b)·lcm(a,b)=ab.', src: '783e19964686' },
  'amc10-0031': { front: 'What is the Euclidean algorithm?', back: 'gcd(a,b)=gcd(b, a mod b), repeated until the remainder is 0.', src: 'b6419f2a6626' },
  'amc10-0032': { front: 'If n=p₁^a₁…p_k^a_k, how many positive divisors does n have?', back: '(a₁+1)…(a_k+1).', src: 'c5bc70e6af3b' },
  'amc10-0033': { front: 'If n=p₁^a₁…p_k^a_k, what is the sum of its positive divisors?', back: '∏(1+p_i+…+p_i^{a_i}).', src: 'b09605b3b1a5' },
  'amc10-0034': { front: 'What is the product of all positive divisors?', back: 'n^{d(n)/2}; for a perfect square the middle √n still pairs with itself.', src: 'c10cda258471' },
  'amc10-0035': { front: 'What prime-factor condition makes an integer a perfect square?', back: 'Every prime exponent is even.', src: '25c8891ff9ea' },
  'amc10-0036': { front: 'What prime-factor condition makes an integer a perfect cube?', back: 'Every prime exponent is a multiple of 3.', src: '23b761d486dd' },
  'amc10-0037': { front: 'How do you find the smallest positive multiplier that turns n into a square?', back: 'Raise every odd exponent in its prime factorization by one.', src: '7c9c2c434b02' },
  'amc10-0038': { front: 'What is the test for divisibility by 2?', back: 'The units digit is even.', src: '8a5e052878e7' },
  'amc10-0039': { front: 'What is the test for divisibility by 3?', back: 'The sum of the digits is divisible by 3.', src: 'ab0437b3e97c' },
  'amc10-0040': { front: 'What is the test for divisibility by 4?', back: 'The number formed by the last two digits is divisible by 4.', src: '227bbc40df6e' },
  'amc10-0041': { front: 'What is the test for divisibility by 5?', back: 'The units digit is 0 or 5.', src: 'a9baac69d239' },
  'amc10-0042': { front: 'What is the test for divisibility by 8?', back: 'The number formed by the last three digits is divisible by 8.', src: '5dea2acd6f36' },
  'amc10-0043': { front: 'What is the test for divisibility by 9?', back: 'The sum of the digits is divisible by 9.', src: '233c95f33c82' },
  'amc10-0044': { front: 'What is the test for divisibility by 10?', back: 'The units digit is 0.', src: '82f718d7062a' },
  'amc10-0045': { front: 'What is the test for divisibility by 11?', back: 'The difference between the alternating sums of the digits is divisible by 11.', src: '722323bc6292' },
  'amc10-0046': { front: 'If a prime p divides ab, what follows?', back: 'p divides a or p divides b; this does not carry over directly to composite numbers.', src: 'fa5c23395b1d' },
  'amc10-0047': { front: 'What does it mean for two integers to be coprime?', back: 'Their gcd is 1; neither number has to be prime.', src: '66d16251ae21' },
  'amc10-0048': { front: 'What is true of the gcd of consecutive integers?', back: 'Two consecutive integers are always coprime.', src: 'a3216dbf64fd' },
  'amc10-0049': { front: 'How do you find the exponent of a prime p in n!?', back: '⌊n/p⌋+⌊n/p²⌋+…', src: '806bf08ab68e' },
  'amc10-0050': { front: 'How do you count the trailing zeros of n!?', back: 'Count the exponent of 5, since factors of 2 are more plentiful.', src: 'c73b663fc85c' },
  'amc10-0051': { front: 'Where is the sum of a factor pair smallest?', back: 'Near √n; with integers, check the neighbouring factor pairs directly.', src: '7eb48870226f' },
  'amc10-0052': { front: 'What factor structure does the difference of squares a²-b² have?', back: '(a-b)(a+b), where the two factors share the same parity.', src: '2f1ae864cac9' },
  'amc10-0053': { front: 'What does a≡b (mod m) mean?', back: 'm divides (a-b), that is, a and b leave the same remainder on division by m.', src: '5254c61992a0' },
  'amc10-0054': { front: 'Which operations are allowed on congruences?', back: 'You may add, subtract and multiply modulo the same m; powers are unconditional only for non-negative integer exponents — to use a negative exponent you must first confirm gcd(a,m)=1.', src: 'c6d295df782d' },
  'amc10-0055': { front: 'Can you cancel freely inside a congruence?', back: 'No; it is only safe when the cancelled number is coprime to the modulus, or when you shrink the modulus correctly at the same time.', src: 'a95eb3f92899' },
  'amc10-0056': { front: 'What is the usual method for the last digit of a large power?', back: 'Look at the cycle of the powers modulo 10.', src: '5e9a6448fe8a' },
  'amc10-0057': { front: 'Which modulus do you use for the last two digits?', back: 'Modulo 100.', src: 'f43daa317a1e' },
  'amc10-0058': { front: 'Why shrink the base before taking a power?', back: 'If a≡r (mod m) then a^n≡r^n (mod m), so the arithmetic stays small.', src: '5370be5e14e8' },
  'amc10-0059': { front: 'Which modulus corresponds to parity?', back: 'Modulo 2.', src: 'a3e2a4bc0da8' },
  'amc10-0060': { front: 'What values can a perfect square take modulo 4?', back: '0 or 1.', src: '97963c7b2303' },
  'amc10-0061': { front: 'What values can a perfect square take modulo 8?', back: '0, 1 or 4; an odd square is 1 modulo 8.', src: '6fbb3aea4ffc' },
  'amc10-0062': { front: 'What values can a perfect square take modulo 3?', back: '0 or 1.', src: '980cbaa764ec' },
  'amc10-0063': { front: 'Why does the digit sum decide divisibility by 9?', back: '10≡1 (mod 9), so the number is congruent to its digit sum.', src: '58058a9073e9' },
  'amc10-0064': { front: 'Why does the alternating digit sum decide divisibility by 11?', back: '10≡-1 (mod 11).', src: '1ad75519b5e6' },
  'amc10-0065': { front: 'When does the linear congruence ax≡b (mod m) have a solution?', back: 'Exactly when gcd(a,m) divides b.', src: '091352c616ce' },
  'amc10-0066': { front: 'When gcd(a,m)=1, how do you solve ax≡b?', back: 'Find the modular inverse of a and multiply both sides by it.', src: '3e17942cade9' },
  'amc10-0067': { front: 'How do you handle several coprime modular conditions?', back: 'List candidates step by step, or merge the periods in the spirit of the Chinese remainder theorem; AMC 10 rarely needs the general formula.', src: '2426ae51bd9b' },
  'amc10-0068': { front: 'What is the first step in a periodic sequence problem?', back: 'Write out enough terms to pin down the start, the period length and the index offset.', src: '30682620df18' },
  'amc10-0069': { front: 'What is the value of the base-b number (a_na_{n-1}…a_0)_b?', back: 'Σ a_i b^i, with 0≤a_i<b for every digit.', src: '8e57daf2cc9f' },
  'amc10-0070': { front: 'How do you convert a decimal integer to base b?', back: 'Divide repeatedly by b and read the remainders in reverse order.', src: 'caf804dd4235' },
  'amc10-0071': { front: 'What range does an n-digit base-b positive integer cover?', back: 'From b^{n-1} to b^n-1.', src: 'ff7d59aecf72' },
  'amc10-0072': { front: 'What is the two-digit number 10a+b when its digits are reversed?', back: '10b+a; the difference between the two is 9(a-b).', src: '2225ad2b5c12' },
  'amc10-0073': { front: 'How do you translate the three-digit number 100a+10b+c?', back: 'Write it by place value directly, with the leading digit a≠0.', src: '299db097df8c' },
  'amc10-0074': { front: 'What do digit-construction problems most often forget?', back: 'That the leading digit cannot be 0, whether digits may repeat, and the digit and base ranges.', src: 'c5f92d2dd3aa' },
  'amc10-0075': { front: 'When does the linear Diophantine equation ax+by=c have integer solutions?', back: 'Exactly when gcd(a,b) divides c.', src: 'f15c40c7972c' },
  'amc10-0076': { front: 'How do you parametrize all integer solutions of a linear Diophantine equation?', back: 'Start from one particular solution: x=x₀+(b/g)t and y=y₀-(a/g)t, where g=gcd(a,b).', src: '3438de9b94bf' },
  'amc10-0077': { front: 'What is the difference between positive and non-negative integer solutions?', back: 'Positive means at least 1; non-negative allows 0, which changes the range of the parameter.', src: '42132c6aa1f9' },
  'amc10-0078': { front: 'What is the two-variable Frobenius result?', back: 'For coprime positive a and b, the largest number not representable as ax+by is ab-a-b; use it only when its conditions hold.', src: '2fd2178669b2' },
  'amc10-0079': { front: 'What is the basic rational root theorem statement?', back: 'An integer root of a monic polynomial with integer coefficients must divide the constant term.', src: '86bf83da8041' },
  'amc10-0080': { front: 'How is an integrality condition usually turned into algebra?', back: 'Use division with remainder, factoring, or a congruence saying the denominator divides the numerator.', src: '967ff48fa67c' },
  'amc10-0081': { front: 'What tools usually prove that no integer solution exists?', back: 'Parity, mod 3/4/8/9, quadratic residues, or the parity of factors.', src: '5237ea0b9762' },
  'amc10-0082': { front: 'If xy is a perfect square, must x and y both be squares?', back: 'No; it only means their odd prime exponents can be paired up across the two numbers.', src: '893604ae7f5a' },
  'amc10-0083': { front: 'What is the difference between a percentage point and a percentage change?', back: 'Going from 40% to 50% is 10 percentage points, which is a 25% relative increase.', src: '45724d281533' },
  'amc10-0084': { front: 'What is the simple interest model?', back: 'Amount A=P(1+rt); each period earns interest on the original principal only.', src: '880d5335a6bc' },
  'amc10-0085': { front: 'What is the compound interest model?', back: 'Per period: rate r per period over n periods, A=P(1+r)^n. Annual nominal rate r compounded m times a year for t years, A=P(1+r/m)^{mt}. The two forms use r for different things, and n and t are not the same unit.', src: 'bc6dc8a7cb25' },
  'amc10-0086': { front: 'How are profit and profit rate computed?', back: 'Profit = selling price − cost; the denominator of the rate has to be read from the question, usually the cost.', src: 'f775d1c53efd' },
  'amc10-0087': { front: 'What are a boat’s downstream and upstream speeds?', back: 'The still-water speed plus or minus the current speed.', src: 'd86b5f2b2194' },
  'amc10-0088': { front: 'How do you model a chase on a circular track?', back: 'From the same starting point, the first catch-up in the same direction covers one full lap: time = lap length / speed difference. If the start gap is g, time = g / speed difference. Head-on meetings use the sum of the speeds.', src: 'a0552bb5e511' },
  'amc10-0089': { front: 'What is the median?', back: 'The middle value once the data is sorted; with an even count, the average of the two middle values.', src: '02a45c8f7068' },
  'amc10-0090': { front: 'What is the mode?', back: 'The most frequent value; there may be none, or more than one.', src: '1f3959ff8985' },
  'amc10-0091': { front: 'What is the range of a data set?', back: 'The maximum minus the minimum.', src: 'a86e758987ae' },
  'amc10-0092': { front: 'How do you update an average after adding one new value?', back: 'Recover the old total from the old average, add the new value, then divide by the new count.', src: '6852f6a96b02' },
  'amc10-0093': { front: 'How do you count the multiples of d in an interval?', back: 'In 1..N it is ⌊N/d⌋; in [L,R] it is ⌊R/d⌋-⌊(L-1)/d⌋.', src: 'b7a8eeb7c846' },
  'amc10-0094': { front: 'Being divisible by both a and b is equivalent to what?', back: 'Being divisible by lcm(a,b).', src: 'f5379a422060' },
  'amc10-0095': { front: 'How do you count numbers divisible by a or b without double counting?', back: 'Add the two counts, then subtract the multiples of lcm(a,b).', src: '171a6f3ac776' },
  'amc10-0096': { front: 'What is the test for divisibility by 6?', back: 'Divisible by both 2 and 3.', src: '0f452218bc97' },
  'amc10-0097': { front: 'What is the test for divisibility by 12?', back: 'Divisible by both 3 and 4.', src: '7c97c651af88' },
  'amc10-0098': { front: 'What characterizes the reduced denominator of a terminating decimal?', back: 'Its only prime factors are 2 and 5.', src: '69499a1c5321' },
  'amc10-0099': { front: 'How do you turn a repeating decimal into a fraction?', back: 'Name it as a variable, multiply by a suitable power of 10 so the repeating blocks line up, then subtract.', src: '12e6ba7e167b' },
  'amc10-0100': { front: 'How do you tell whether √n is rational?', back: 'For an integer n≥0, √n is an integer and therefore rational only when n is a perfect square.', src: '5f1e728cd5a3' },
  'amc10-0101': { front: 'What is the square-free part?', back: 'The product left after removing every even power from the prime factorization; it is used to combine and compare radicals.', src: '809069a82d7f' },
  'amc10-0102': { front: '⌊√n⌋=k is equivalent to what?', back: 'k²≤n<(k+1)².', src: '9432d9488162' },
  'amc10-0103': { front: 'What is Fermat’s little theorem?', back: 'For a prime p that does not divide a, a^{p-1}≡1 (mod p).', src: '21516e646008' },
  'amc10-0104': { front: 'What is Euler’s theorem?', back: 'When gcd(a,n)=1, a^{φ(n)}≡1 (mod n).', src: '766791dca948' },
  'amc10-0105': { front: 'What does Euler’s totient φ(n) count?', back: 'The integers in 1..n that are coprime to n; if n=∏p_i^{a_i} then φ(n)=n∏(1-1/p_i).', src: 'ef67b4559324' },
  'amc10-0106': { front: 'When does the Chinese remainder idea give a unique periodic solution?', back: 'When the moduli are pairwise coprime, the simultaneous congruences have a unique solution modulo their product.', src: '0f4b8734621a' },
  'amc10-0107': { front: 'Why must you check coprimality before using Fermat or Euler?', back: 'If the base shares a prime factor with the modulus, reducing the exponent modulo the period can fail.', src: 'add8eeb53df6' },
  'amc10-0108': { front: 'What is the p-adic valuation v_p(n)?', back: 'The exponent of the prime p in the factorization of n; it adds under multiplication and compares exponents under divisibility.', src: '15d8a4342ffe' },
  'amc10-0109': { front: 'What happens to an integer polynomial at congruent inputs?', back: 'If a≡b (mod m) then P(a)≡P(b) (mod m) for any polynomial with integer coefficients.', src: '66e9ae7ebd50' },
  'amc10-0110': { front: 'How do you describe a randomly chosen positive divisor?', back: 'Choose each prime exponent from 0..a_i; if all divisors are equally likely then the exponent vectors are equally likely.', src: '442ee0a96840' },
  'amc10-0111': { front: 'Why write the domain before solving an equation?', back: 'To rule out zero denominators, negative values under an even root, and other meaningless values.', src: '3aefee8be97f' },
  'amc10-0112': { front: 'What is the standard procedure for a fractional equation?', back: 'Write the restrictions, multiply by the lowest common denominator, solve the polynomial equation, then check the roots.', src: '3bad43825b4b' },
  'amc10-0113': { front: 'Why must the answers to a radical equation be checked?', back: 'Squaring can introduce extraneous roots.', src: '71cd02f65815' },
  'amc10-0114': { front: 'What are the usual methods for a system of two linear equations?', back: 'Substitution or elimination, or working directly with the sum and difference structure.', src: '56d631c3621c' },
  'amc10-0115': { front: 'When is it fine to set the total to a convenient number?', back: 'When only ratios or percentages are given and the answer does not depend on the scale.', src: 'a0bb3704f7bb' },
  'amc10-0116': { front: 'What is the goal of a substitution?', back: 'Treat a repeated structure as a single variable, which lowers the degree or cuts the number of terms.', src: '6df4adc36892' },
  'amc10-0117': { front: 'What substitution is standard in symmetric expressions?', back: 's=x+y and p=xy.', src: '702ea9745d80' },
  'amc10-0118': { front: 'How do you write x²+y² in terms of s=x+y and p=xy?', back: 's²-2p.', src: 'd7ee6c4adb8d' },
  'amc10-0119': { front: 'How is x³+y³ expressed?', back: '(x+y)³-3xy(x+y)=s³-3ps.', src: '9d1b6ada05c7' },
  'amc10-0120': { front: 'How do you combine 1/x+1/y?', back: '(x+y)/(xy), provided xy≠0.', src: 'b2de19c8ec31' },
  'amc10-0121': { front: 'How do you solve |x|=a?', back: 'No solution when a<0; x=0 when a=0; x=±a when a>0.', src: 'a880cb2cb83a' },
  'amc10-0122': { front: 'What is the geometric meaning of |x-a|?', back: 'The distance from x to a on the number line.', src: 'bde7741403c6' },
  'amc10-0123': { front: 'What is a reliable way to solve an equation with several absolute values?', back: 'Split the line at every critical point and check each piece against its own range.', src: 'f75bad7c86d2' },
  'amc10-0124': { front: '⌊x⌋=n is equivalent to what?', back: 'n≤x<n+1, with n an integer.', src: '410a2b60e387' },
  'amc10-0125': { front: '⌈x⌉=n is equivalent to what?', back: 'n-1<x≤n, with n an integer.', src: '0b304baad68f' },
  'amc10-0126': { front: 'Why split an equation with ⌊x⌋ into an integer and a fractional part?', back: 'Writing x=n+r with n∈Z and 0≤r<1 pins down exactly where the jumps happen.', src: '688a669891d6' },
  'amc10-0127': { front: 'What is the quadratic formula?', back: 'x=(-b±√(b²-4ac))/(2a), with a≠0.', src: 'bc537026ffdf' },
  'amc10-0128': { front: 'What is the discriminant?', back: 'Δ=b²-4ac; it decides how many real roots the equation has.', src: '2cdc2be7f3a9' },
  'amc10-0129': { front: 'What makes a quadratic have two, one or no real roots?', back: 'Δ>0, Δ=0 and Δ<0 respectively.', src: '9f2008071525' },
  'amc10-0130': { front: 'What is Vieta’s formula?', back: 'If the roots are r and s then r+s=-b/a and rs=c/a.', src: 'c7bf628cd5e1' },
  'amc10-0131': { front: 'What is the monic quadratic with roots r and s?', back: '(x-r)(x-s)=x²-(r+s)x+rs.', src: '1787a94b7925' },
  'amc10-0132': { front: 'What is the axis of symmetry of ax²+bx+c?', back: 'x=-b/(2a).', src: '5c0a313268fe' },
  'amc10-0133': { front: 'How do you find the y-coordinate of a parabola’s vertex?', back: 'Substitute x=-b/(2a), or complete the square.', src: '18d478dff56e' },
  'amc10-0134': { front: 'What is the basic completing-the-square form?', back: 'x²+bx=(x+b/2)²-b²/4.', src: '3e68d2a22b73' },
  'amc10-0135': { front: 'What decides a quadratic’s maximum or minimum?', back: 'The opening direction and the vertex; a>0 gives a minimum and a<0 a maximum.', src: '57682dadb992' },
  'amc10-0136': { front: 'When does a quadratic with integer coefficients have integer roots?', back: 'The discriminant must be a perfect square, and the numerator of the quadratic formula must be divisible by 2a.', src: '3636a128e195' },
  'amc10-0137': { front: 'What is the factor theorem?', back: 'P(r)=0 exactly when x-r is a factor of P(x).', src: '99b5da2902b5' },
  'amc10-0138': { front: 'What is the remainder theorem?', back: 'The remainder when P(x) is divided by x-r is P(r).', src: '525d3ff3f913' },
  'amc10-0139': { front: 'What does the remainder look like when dividing by a quadratic?', back: 'Its degree is below 2, so it is ax+b.', src: '271bae664ecd' },
  'amc10-0140': { front: 'How do you find unknown coefficients in a polynomial identity?', back: 'Expand and compare coefficients, or substitute enough convenient values.', src: 'dd6e589a8cac' },
  'amc10-0141': { front: 'What techniques does an integer-valued polynomial problem usually need?', back: 'Differences at consecutive inputs, factoring modulo something, the remainder theorem, or integer-root restrictions.', src: 'a958fd41d959' },
  'amc10-0142': { front: 'What is the rule for multiplying powers with the same base?', back: 'a^m a^n=a^{m+n}.', src: 'a3dbb831a454' },
  'amc10-0143': { front: 'What is the power-of-a-power rule?', back: '(a^m)^n=a^{mn}, provided a>0 or both m and n are integers.', src: '5c4ddd3f73cc' },
  'amc10-0144': { front: 'What does a negative exponent mean?', back: 'a^{-n}=1/a^n, with a≠0.', src: '71ce471441d9' },
  'amc10-0145': { front: 'What is the zero exponent rule?', back: 'a^0=1, with a≠0.', src: '59a671647f14' },
  'amc10-0146': { front: 'How is a fractional exponent interpreted?', back: 'a^{m/n}=ⁿ√(a^m), which needs a≥0 (or m/n already in lowest terms with n odd).', src: '4fae273821e9' },
  'amc10-0147': { front: 'What is √(a²)?', back: '|a|, which is not always equal to a.', src: '96d85969f196' },
  'amc10-0148': { front: 'When can radicals be added together?', back: 'Only after reducing them to the same radical factor, at which point the coefficients combine.', src: 'd7ff50991b73' },
  'amc10-0149': { front: 'How do you rationalize 1/(√a+√b)?', back: 'Multiply by the conjugate √a-√b.', src: 'f3c601b59dfa' },
  'amc10-0150': { front: 'What is the usual telescoping split for fractions?', back: '1/[n(n+1)]=1/n-1/(n+1).', src: '1d9507d66aae' },
  'amc10-0151': { front: 'How do you split 1/[(n+a)(n+b)]?', back: 'Write it as 1/(b-a)·(1/(n+a)-1/(n+b)), which needs b≠a.', src: '6bc5a604ad0e' },
  'amc10-0152': { front: 'What is the first choice for an exponential equation?', back: 'Get both sides onto the same base, then compare the exponents.', src: 'c3631a499b91' },
  'amc10-0153': { front: 'When a sum of radicals should collapse to a single radical, what should you check?', back: 'Whether the cross term after squaring is an integer or a like radical, and whether the signs match the original expression.', src: 'b08ad4dc59a4' },
  'amc10-0154': { front: 'What is the definition of a function?', back: 'Every allowed input has exactly one output.', src: 'ff4f692f5a65' },
  'amc10-0155': { front: 'What is the domain of a function?', back: 'The set of all allowed inputs.', src: '4f9602107a74' },
  'amc10-0156': { front: 'What is the range of a function?', back: 'The set of all possible outputs.', src: '10439f36fb9c' },
  'amc10-0157': { front: 'What does f(a) mean?', back: 'Substitute the input a into the rule; it is not f times a.', src: '2181662a9b89' },
  'amc10-0158': { front: 'How do you evaluate the composite f(g(x))?', back: 'Work out the inner g(x) first, then feed that result into f.', src: '226bfa0aff71' },
  'amc10-0159': { front: 'What is the key condition for an inverse function to exist?', back: 'The function must be one-to-one on the domain in question.', src: 'a00ec3b6e5c9' },
  'amc10-0160': { front: 'How does the graph of y=f(x)+k move?', back: 'Up by k vertically; k<0 moves it down.', src: 'd9e96b01cd18' },
  'amc10-0161': { front: 'How does the graph of y=f(x-h) move?', back: 'Right by h horizontally; inside the bracket the direction is reversed.', src: '5a60442c455d' },
  'amc10-0162': { front: 'What reflections are y=-f(x) and y=f(-x)?', back: 'The first is a reflection about the x-axis, the second about the y-axis.', src: 'a322007625cd' },
  'amc10-0163': { front: 'What is the test for an even function?', back: 'f(-x)=f(x), so the graph is symmetric about the y-axis.', src: '9f3a965ac33c' },
  'amc10-0164': { front: 'What is the test for an odd function?', back: 'f(-x)=-f(x), so the graph is symmetric about the origin.', src: 'fc2830db48c8' },
  'amc10-0165': { front: 'How do you find where two graphs meet?', back: 'Set the outputs equal, that is, solve f(x)=g(x).', src: '2342a5217cea' },
  'amc10-0166': { front: 'What does iterating a function mean?', back: 'f^{(n)}(x) means repeated composition, not [f(x)]^n in the usual sense.', src: 'df94fdefb51f' },
  'amc10-0167': { front: 'What must you check in a piecewise function?', back: 'Which piece the input falls in, and which piece owns the endpoint.', src: '8885832f8b5e' },
  'amc10-0168': { front: 'Do graph transformations commute?', back: 'Usually not; track one general point through the composition in order.', src: 'b3107a42dbef' },
  'amc10-0169': { front: 'What is the general term of an arithmetic sequence?', back: 'a_n=a_1+(n-1)d.', src: '06308ced4317' },
  'amc10-0170': { front: 'What is the sum of the first n terms of an arithmetic sequence?', back: 'S_n=n(a_1+a_n)/2=n[2a_1+(n-1)d]/2.', src: '84931f783655' },
  'amc10-0171': { front: 'What is the general term of a geometric sequence?', back: 'a_n=a_1r^{n-1}.', src: '6f1145c927d0' },
  'amc10-0172': { front: 'What is the sum of the first n terms of a geometric sequence?', back: 'S_n=a_1(1-r^n)/(1-r), with r≠1.', src: '60c1455a0815' },
  'amc10-0173': { front: 'When does an infinite geometric series converge?', back: 'When |r|<1, and then its sum is a_1/(1-r).', src: 'fb76d645e08d' },
  'amc10-0174': { front: 'What is the first step with a recursively defined sequence?', back: 'Write out the first several terms and look for a cycle, monotonicity, parity, or an invariant.', src: '74d466ba9173' },
  'amc10-0175': { front: 'What is the most common indexing mistake?', back: 'Writing the nth term as if it took n steps; there are usually n-1 steps from a_1 to a_n.', src: '0ad08dece02c' },
  'amc10-0176': { front: 'How do you find the fixed point of the recursion a_{n+1}=ra_n+c?', back: 'Solve L=rL+c (which needs r≠1; r=1 degenerates to an arithmetic sequence), then study the geometric behaviour of a_n-L.', src: '8d8518058ce3' },
  'amc10-0177': { front: 'How do you handle a huge index in a periodic recursion?', back: 'Establish the full period and where it starts, then reduce the index offset modulo the period.', src: '29d4086d2a7a' },
  'amc10-0178': { front: 'What signals a telescoping sum?', back: 'Splitting consecutive terms so that most of them cancel in pairs.', src: 'b3b544db2404' },
  'amc10-0179': { front: 'What strategies work for a Fibonacci-style recursion?', back: 'List terms, use a modular period, look for relations between neighbouring terms, or use partial-sum identities.', src: '71da85ebd560' },
  'amc10-0180': { front: 'What happens to an inequality when you multiply or divide by a negative number?', back: 'The direction flips.', src: '959e8a3e4b12' },
  'amc10-0181': { front: 'Why can’t you just multiply a rational inequality by the denominator?', back: 'The sign of the denominator is unknown; move everything to one side and do a sign analysis instead.', src: '46c1f7e574a2' },
  'amc10-0182': { front: 'What is the number-line form of the triangle inequality?', back: '|x-a|+|x-b|≥|a-b|, with equality exactly when x lies between a and b (where the minimum |a-b| is attained).', src: '048bc3ad20e3' },
  'amc10-0183': { front: 'What is two-variable AM-GM?', back: 'For x,y≥0, (x+y)/2≥√xy, with equality at x=y.', src: 'f0efc4ad9d9e' },
  'amc10-0184': { front: 'With a fixed sum, when is the product largest?', back: 'When the non-negative variables are as equal as possible.', src: '88aeab1b0af9' },
  'amc10-0185': { front: 'With a fixed product, when is the sum smallest?', back: 'When the positive variables are as equal as possible.', src: 'cb18a9133c4b' },
  'amc10-0186': { front: 'What is the multi-variable AM-GM?', back: 'The arithmetic mean of non-negative numbers is at least their geometric mean, with equality when all of them are equal.', src: 'd90ae3b65353' },
  'amc10-0187': { front: 'What is the practical substitute for weighted AM-GM?', back: 'Duplicate variables according to the exponent: to control x²y, consider x, x, y.', src: 'e7c54e4fdaeb' },
  'amc10-0188': { front: 'What is the sum-of-squares form of Cauchy?', back: '(Σa_i²)(Σb_i²)≥(Σa_ib_i)², with equality exactly when the two sequences are proportional.', src: '41d0fb53cfba' },
  'amc10-0189': { front: 'What is the lower bound on the sum of squares of n numbers?', back: 'Σx_i²≥(Σx_i)²/n, with equality when all are equal.', src: '947ee322136d' },
  'amc10-0190': { front: 'What is the Titu/Engel form?', back: 'With positive denominators, Σa_i²/x_i≥(Σa_i)²/(Σx_i), with equality exactly when all a_i/x_i are equal.', src: '57d141929dc9' },
  'amc10-0191': { front: 'What is the lower bound on 1/x+1/y when x+y=S?', back: '4/S, attained for positive x=y.', src: '78f0113b61b8' },
  'amc10-0192': { front: 'What is QM-AM?', back: 'The root mean square is at least the arithmetic mean: √(Σa_i²/n)≥Σa_i/n, which holds for all real numbers, with equality exactly when all terms are equal and that common value is ≥0; it follows directly from Cauchy.', src: '0508e01a4c05' },
  'amc10-0193': { front: 'How do you maximize a linear expression under a fixed sum of squares?', back: 'Use Cauchy; equality holds when the variables are proportional to the coefficient vector.', src: '581e95e03e07' },
  'amc10-0194': { front: 'After using a continuous extremum on an integer problem, what else must you do?', back: 'Check the nearest integers, the actual factor pairs, and whether the value is reachable under the congruences.', src: '94b01b93b52c' },
  'amc10-0195': { front: 'What is the integer smoothing principle?', back: 'With a fixed sum, if two numbers differ by at least 2, moving 1 from the larger to the smaller usually increases the product.', src: '3b8bfe7cae0c' },
  'amc10-0196': { front: 'What two things must an extremum solution always state?', back: 'A proof of the bound, and a legal example that attains it.', src: '847d0da00158' },
  'amc10-0197': { front: 'How do you choose between completing the square and AM-GM?', back: 'Prefer completing the square for quadratics; use AM-GM when there is a non-negative fixed sum or product.', src: 'b73b36b68e41' },
  'amc10-0198': { front: 'Are Jensen, Holder and Muirhead AMC 10 priorities?', back: 'No; get fluent first with completing the square, AM-GM, Cauchy, Titu and integer attainability.', src: '9cc16fc28135' },
  'amc10-0199': { front: 'What is the solution of ax+b=c when a≠0?', back: 'x=(c-b)/a.', src: 'dea46050db68' },
  'amc10-0200': { front: 'What is the difference between an identity, an equation and a conditional equation?', back: 'An identity holds for every value in the domain, an equation only for its solutions, and a conditional equation only under the given conditions.', src: 'c1846e9fe12e' },
  'amc10-0201': { front: 'What matters most when handling a proportion chain a:b=c:d?', back: 'That the denominators are nonzero, and being clear about which quantities share the same scale factor.', src: '9073b467ad1d' },
  'amc10-0202': { front: 'What is the sum of cubes formula?', back: 'a³+b³=(a+b)(a²-ab+b²).', src: '149a6f0cd3fb' },
  'amc10-0203': { front: 'What is the difference of cubes formula?', back: 'a³-b³=(a-b)(a²+ab+b²).', src: 'f41c4c1e5eb7' },
  'amc10-0204': { front: 'What signals that you should factor by grouping?', back: 'Four or more terms that split into groups sharing a common binomial factor.', src: '05fcb2b89b15' },
  'amc10-0205': { front: 'What does the multiplicity of a root mean?', back: 'When (x-r)^k divides the polynomial but no higher power does, r is a root of multiplicity k.', src: '194080b4486f' },
  'amc10-0206': { front: 'When dividing by (x-a)(x-b) with a≠b, how do you pin down the linear remainder?', back: 'Write the remainder as R(x)=mx+n and use R(a)=P(a) and R(b)=P(b) to find the coefficients.', src: 'dd382c20e4ca' },
  'amc10-0207': { front: 'What are the rational root candidates when the leading coefficient is not 1?', back: 'A reduced root p/q satisfies p dividing the constant term and q dividing the leading coefficient.', src: 'fcbcadc07c5f' },
  'amc10-0208': { front: 'What is the binomial theorem?', back: '(x+y)^n=Σ_{k=0}^n C(n,k)x^{n-k}y^k.', src: '28bae02b571a' },
  'amc10-0209': { front: 'What is the coefficient of x^{n-k}y^k in (x+y)^n?', back: 'C(n,k).', src: '852a21083e84' },
  'amc10-0210': { front: 'How do you get the sums of the even and odd binomial coefficients?', back: 'Compare (1+1)^n with (1-1)^n; both sums equal 2^{n-1} for n≥1.', src: 'c5799c535d06' },
  'amc10-0211': { front: 'What do |x-a|<r and |x-a|≤r mean?', back: 'They mean a-r<x<a+r and a-r≤x≤a+r respectively.', src: '896c8b9cf64a' },
  'amc10-0212': { front: 'What does |x-a|>r mean?', back: 'x<a-r or x>a+r, provided r≥0.', src: 'b009413732a2' },
  'amc10-0213': { front: 'How do you solve a quadratic inequality with a sign table?', back: 'Find the zeros and the excluded points, test the sign of each factor on each interval, then handle the endpoints.', src: 'dec3f138c457' },
  'amc10-0214': { front: 'How does a square being non-negative give a useful bound?', back: 'From (x-y)²≥0 you get x²+y²≥2xy, or you complete a square starting from (x-a)²≥0.', src: '9490f677dd73' },
  'amc10-0215': { front: 'How is the discriminant used for a parameter extremum?', back: 'Write the condition as a quadratic in some variable; a real solution requires Δ≥0, and the boundary is usually at Δ=0.', src: '1693dbaad5a9' },
  'amc10-0216': { front: 'What is the intuitive version of the rearrangement inequality?', back: 'Pairing two similarly ordered sequences maximises the sum of products and pairing them oppositely minimises it, with the extremes when the orders agree or reverse completely.', src: 'a3898bbd2d6d' },
  'amc10-0217': { front: 'Where do you check an extremum of a monotone function on a closed interval?', back: 'If you can prove monotonicity, only the endpoints need checking.', src: 'cfdec8dad469' },
  'amc10-0218': { front: 'How do you find the minimum of a convex quadratic over integer points?', back: 'Find the real vertex first, then check the nearest integers on either side of it.', src: '775cd677a0f6' },
  'amc10-0219': { front: 'What do m and b mean in y=mx+b?', back: 'The slope and the y-intercept.', src: '2a875395a7f0' },
  'amc10-0220': { front: 'What is a zero of a function?', back: 'An input with f(x)=0, that is, where the graph meets the x-axis.', src: '7e17e3c2fa13' },
  'amc10-0221': { front: 'How do you find an inverse function from the equation?', back: 'Write y=f(x), swap x and y, solve for y, then check one-to-one-ness and the domain.', src: '8ae30276dc72' },
  'amc10-0222': { front: 'How should you read the horizontal stretch y=f(bx)?', back: 'The x-coordinates scale by 1/|b|; if b<0 there is also a reflection in the y-axis.', src: '686fd28c9147' },
  'amc10-0223': { front: 'What substitutions usually crack a functional equation?', back: 'Try 0, 1, equal variables, negatives, or force the inner expression to take a special value.', src: 'b02461db1d75' },
  'amc10-0224': { front: 'What do the mean, median and mode each reflect?', back: 'The mean uses every value, the median is the centre of the ordering, and the mode is the most frequent value.', src: '646b50860824' },
  'amc10-0225': { front: 'Which statistic is most easily distorted by an outlier?', back: 'The mean; the median is usually more robust.', src: 'c9ddb88056d1' },
  'amc10-0226': { front: 'Why is the variance never negative?', back: 'Each (x_i-x̄)²≥0, so the total is at least 0 and is exactly 0 only when every value is equal.', src: 'd9ddfcd01d41' },
  'amc10-0227': { front: 'How do you take the mean from a frequency table?', back: 'Σ(value×frequency)/total frequency.', src: 'a93a09b58111' },
  'amc10-0228': { front: 'What is the key difference between a histogram and a bar chart?', back: 'A histogram shows numeric intervals with the bars usually touching; a bar chart shows categories.', src: 'fa623b9d4456' },
  'amc10-0229': { front: 'How do you recognise a mixed arithmetic-geometric sequence?', back: 'Check the successive differences, the successive ratios, the odd and even subsequences, or a block pattern, rather than forcing a single model.', src: 'e62daf09829c' },
  'amc10-0230': { front: 'How do you usually handle a two-dimensional recursion table?', back: 'Fill a small table from the boundary, then look for Pascal-style addition, symmetry, or a path-counting interpretation.', src: '0a08a34ef368' },
  'amc10-0231': { front: 'How do partial sums S_n relate to the general term?', back: 'a_n=S_n-S_{n-1} for n≥2, and a_1=S_1.', src: '7d88248f2094' },
  'amc10-0232': { front: 'What is the relationship between vertical angles?', back: 'They are equal.', src: '8610ff55e46e' },
  'amc10-0233': { front: 'What do adjacent angles on a straight line sum to?', back: '180°.', src: '3eed9934db99' },
  'amc10-0234': { front: 'What is the full angle around a point?', back: '360°.', src: 'd9495f6916a2' },
  'amc10-0235': { front: 'What angle relations appear when a transversal cuts parallel lines?', back: 'Corresponding angles are equal, alternate interior angles are equal, and co-interior angles are supplementary.', src: '91ca869e47f8' },
  'amc10-0236': { front: 'What do the interior angles of a triangle sum to?', back: '180°.', src: 'c950f2cfe22f' },
  'amc10-0237': { front: 'What is the exterior angle theorem for a triangle?', back: 'An exterior angle equals the sum of the two non-adjacent interior angles.', src: 'ca295be576b2' },
  'amc10-0238': { front: 'What is the sum of the interior angles of an n-gon?', back: '(n-2)·180°.', src: '90ed4e5a26b0' },
  'amc10-0239': { front: 'What is the sum of the exterior angles of any convex polygon?', back: '360°.', src: 'f13aee5f3eba' },
  'amc10-0240': { front: 'What is each interior angle of a regular n-gon?', back: '(n-2)180°/n.', src: 'c3b75df550cc' },
  'amc10-0241': { front: 'What is each exterior or central angle of a regular n-gon?', back: '360°/n.', src: '1422b59d21b2' },
  'amc10-0242': { front: 'What is the triangle inequality?', back: 'The sum of any two sides is strictly greater than the third.', src: 'af8f7e88e3d6' },
  'amc10-0243': { front: 'With two sides fixed, what range can the third side c take?', back: '|a-b|<c<a+b.', src: 'd9c4073c6ab4' },
  'amc10-0244': { front: 'What are the basic properties of an isosceles triangle?', back: 'Equal sides face equal angles, and the apex bisector is also the median and the altitude to the base.', src: '3435edefc98e' },
  'amc10-0245': { front: 'What are the height and area of an equilateral triangle?', back: 'Height √3s/2, area √3s²/4.', src: '96467c36a8c4' },
  'amc10-0246': { front: 'What are the congruence tests for triangles?', back: 'SSS, SAS, ASA and AAS, plus HL for right triangles.', src: '76eea4e59bff' },
  'amc10-0247': { front: 'Why is SSA usually not a congruence test?', back: 'Two different triangles can satisfy the same data.', src: 'f22223481f24' },
  'amc10-0248': { front: 'What are the similarity tests for triangles?', back: 'AA (two equal angles), SAS (two proportional sides with an equal included angle), and SSS (three proportional sides).', src: 'cd1accea4405' },
  'amc10-0249': { front: 'With similarity ratio k, what are the perimeter and area ratios?', back: 'k and k².', src: 'f51f24589752' },
  'amc10-0250': { front: 'With linear ratio k for similar solids, what are the surface area and volume ratios?', back: 'k² and k³.', src: '43ba4197ebd6' },
  'amc10-0251': { front: 'What is the triangle midsegment theorem?', back: 'The segment joining the midpoints of two sides is parallel to the third side and half its length.', src: '045e758ff461' },
  'amc10-0252': { front: 'What is a median of a triangle?', back: 'The segment from a vertex to the midpoint of the opposite side.', src: 'f126bde55739' },
  'amc10-0253': { front: 'How does the centroid divide a median?', back: 'From vertex to centroid and centroid to side midpoint is a 2:1 ratio.', src: '78bd85126b6f' },
  'amc10-0254': { front: 'What is the angle bisector theorem?', back: 'An interior angle bisector divides the opposite side in the ratio of the adjacent sides.', src: '2142a7b93853' },
  'amc10-0255': { front: 'What is an altitude of a triangle?', back: 'The perpendicular segment from a vertex to the line containing the opposite side.', src: '37796f0f0bcf' },
  'amc10-0256': { front: 'What is the median length formula?', back: 'm_a²=(2b²+2c²-a²)/4.', src: '6378e1560ec3' },
  'amc10-0257': { front: 'What does Stewart’s theorem describe?', back: 'In triangle ABC with D on BC, BD=m, DC=n (so a=m+n) and AD=d, then b²m+c²n=a(d²+mn); use it only when substituting directly clearly shortens the work.', src: 'fed1a4aefe04' },
  'amc10-0258': { front: 'What is the centroid of a triangle?', back: 'The intersection of the three medians.', src: '1ef46afb104e' },
  'amc10-0259': { front: 'What is the incenter of a triangle?', back: 'The intersection of the three interior angle bisectors.', src: 'b04b3321bea0' },
  'amc10-0260': { front: 'What is the circumcenter of a triangle?', back: 'The intersection of the perpendicular bisectors of the three sides.', src: 'eafd4864913b' },
  'amc10-0261': { front: 'What is the orthocenter of a triangle?', back: 'The intersection of the lines containing the three altitudes.', src: 'f79f1f797361' },
  'amc10-0262': { front: 'What is true of the distances from the incenter to the sides?', back: 'They are equal, and equal to the inradius.', src: '231012b4b741' },
  'amc10-0263': { front: 'What is true of the distances from the circumcenter to the vertices?', back: 'They are equal, and equal to the circumradius.', src: 'a185d0df01e3' },
  'amc10-0264': { front: 'Where is the circumcenter of a right triangle?', back: 'At the midpoint of the hypotenuse.', src: 'c79b3d76a321' },
  'amc10-0265': { front: 'What is the property of the midpoint of a right triangle’s hypotenuse?', back: 'It is equidistant from all three vertices, at half the hypotenuse.', src: '0ed89c0d5887' },
  'amc10-0266': { front: 'What is the basic area formula for a triangle?', back: 'K=bh/2.', src: '82056a661593' },
  'amc10-0267': { front: 'What is the area ratio for two triangles with the same height?', back: 'The ratio of their bases.', src: 'e011e01feaaf' },
  'amc10-0268': { front: 'What is the area ratio for two triangles with the same base?', back: 'The ratio of their heights.', src: '4369314f952f' },
  'amc10-0269': { front: 'What is true of triangles on the same base between parallel lines?', back: 'Their heights are equal, so their areas are equal.', src: 'e5ccc70e54ee' },
  'amc10-0270': { front: 'What is the Pythagorean theorem?', back: 'In a right triangle the sum of the squares of the legs equals the square of the hypotenuse.', src: 'e5e67db88217' },
  'amc10-0271': { front: 'What is the converse of the Pythagorean theorem?', back: 'If the square of the longest side equals the sum of the squares of the other two, the triangle is right-angled.', src: 'dbdf2473aa0c' },
  'amc10-0272': { front: 'Which Pythagorean triples come up most often?', back: '3-4-5, 5-12-13, 7-24-25 and 8-15-17, and their multiples.', src: '7ef8b4f445d1' },
  'amc10-0273': { front: 'What is the parametrization of primitive Pythagorean triples?', back: 'm²-n², 2mn and m²+n², with m>n>0, gcd(m,n)=1 and m, n of opposite parity.', src: 'b522e6ac5e48' },
  'amc10-0274': { front: 'What is the side ratio of a 45-45-90 triangle?', back: '1:1:√2.', src: '236615f4e6f7' },
  'amc10-0275': { front: 'What is the side ratio of a 30-60-90 triangle?', back: '1:√3:2, opposite 30°, 60° and 90° respectively.', src: '4f611cdbb4bf' },
  'amc10-0276': { front: 'How else can you write the area of a right triangle?', back: 'Half the product of the two legs.', src: 'fa14eaa483eb' },
  'amc10-0277': { front: 'What is Heron’s formula?', back: 'K=√[s(s-a)(s-b)(s-c)], with s=(a+b+c)/2.', src: '87bdb33e265c' },
  'amc10-0278': { front: 'How does a triangle’s area relate to its inradius?', back: 'K=rs.', src: 'fdc911121d67' },
  'amc10-0279': { front: 'How does a triangle’s area relate to its circumradius?', back: 'K=abc/(4R); treat it as an advanced tool.', src: '70856221b7c8' },
  'amc10-0280': { front: 'What is the distance formula in the coordinate plane?', back: '√[(x₂-x₁)²+(y₂-y₁)²].', src: 'dae1519a6b45' },
  'amc10-0281': { front: 'What is the midpoint formula?', back: '((x₁+x₂)/2,(y₁+y₂)/2).', src: '5236caaed650' },
  'amc10-0282': { front: 'What is the slope formula?', back: '(y₂-y₁)/(x₂-x₁); a vertical line has no slope.', src: '41c0684c5f9a' },
  'amc10-0283': { front: 'How do the slopes of two non-vertical parallel lines relate?', back: 'They are equal.', src: 'b9a5a65f0f88' },
  'amc10-0284': { front: 'How do the slopes of two non-vertical perpendicular lines relate?', back: 'Their product is -1.', src: 'e87326656567' },
  'amc10-0285': { front: 'How do you find the area of a polygon from its coordinates?', back: 'Cut it up, complete a shape around it, or use the shoelace formula and take half the absolute value.', src: '0034c94da7f9' },
  'amc10-0286': { front: 'What are the properties of a parallelogram?', back: 'Opposite sides are parallel and equal, opposite angles are equal, adjacent angles are supplementary, and the diagonals bisect each other.', src: 'b4a6fcff570b' },
  'amc10-0287': { front: 'What extra properties does a rectangle have?', back: 'All four angles are right angles, and the diagonals are equal.', src: 'ea251dbb465f' },
  'amc10-0288': { front: 'What extra properties does a rhombus have?', back: 'All four sides are equal, and the diagonals are perpendicular and bisect the angles.', src: '1a6d12f08371' },
  'amc10-0289': { front: 'Which properties does a square combine?', back: 'All the properties of both a rectangle and a rhombus.', src: 'fc9ea632397e' },
  'amc10-0290': { front: 'What is the length of a trapezoid’s midsegment?', back: 'Half the sum of the two bases.', src: 'c71e1f5d7570' },
  'amc10-0291': { front: 'What is the area of a parallelogram?', back: 'Base × height.', src: 'b4268779e063' },
  'amc10-0292': { front: 'What is the area of a trapezoid?', back: '(upper base + lower base) × height / 2.', src: 'a85706ebd379' },
  'amc10-0293': { front: 'What is the diagonal formula for the area of a rhombus or a kite?', back: 'Half the product of the perpendicular diagonals.', src: '42a7f98781e1' },
  'amc10-0294': { front: 'How do you split a regular n-gon to find its area?', back: 'Into n congruent isosceles triangles with the centre as their apex.', src: '8c5a22d41655' },
  'amc10-0295': { front: 'How does a regular polygon’s area relate to its perimeter and apothem?', back: 'K=(1/2)·perimeter·apothem.', src: '1673c5dcadbe' },
  'amc10-0296': { front: 'How many diagonals does a polygon have?', back: 'n(n-3)/2.', src: 'a841da0ca208' },
  'amc10-0297': { front: 'What are the circumference and area formulas for a circle?', back: '2πr and πr².', src: 'c2e82b3469b0' },
  'amc10-0298': { front: 'What is the arc length formula?', back: 'θ/360°·2πr.', src: 'e9a1fc7ffaac' },
  'amc10-0299': { front: 'What is the sector area formula?', back: 'θ/360°·πr².', src: '62bfd30b60ef' },
  'amc10-0300': { front: 'How do the inscribed and central angles on the same arc relate?', back: 'The inscribed angle is half the central angle.', src: '18c8c1e5311f' },
  'amc10-0301': { front: 'What is the inscribed angle subtending a diameter?', back: '90°.', src: 'ea7ed1babb50' },
  'amc10-0302': { front: 'How do inscribed angles standing on the same arc relate?', back: 'They are equal.', src: 'bce681e2e751' },
  'amc10-0303': { front: 'What is true of the opposite angles of a cyclic quadrilateral?', back: 'They are supplementary.', src: 'e6aa563f5b47' },
  'amc10-0304': { front: 'How do a radius and a tangent meet at the point of tangency?', back: 'At a right angle.', src: 'f8882a04cbe7' },
  'amc10-0305': { front: 'How do the two tangent segments from the same external point relate?', back: 'They have equal length.', src: '832d991d1633' },
  'amc10-0306': { front: 'Where does the perpendicular bisector of a chord pass?', back: 'Through the centre.', src: '0990ee9907cd' },
  'amc10-0307': { front: 'What is true of the perpendicular from the centre to a chord?', back: 'It bisects the chord.', src: '3b8656f6c86c' },
  'amc10-0308': { front: 'What is the intersecting chords theorem?', back: 'PA·PB=PC·PD.', src: '297c70e593e1' },
  'amc10-0309': { front: 'What is the secant-secant power theorem?', back: 'The product of the external segment and the whole secant is the same on both secants.', src: 'bf3af5ff19d1' },
  'amc10-0310': { front: 'What is the tangent-secant power theorem?', back: 'Tangent length squared = external segment × the whole secant.', src: '643839a2dd7a' },
  'amc10-0311': { front: 'How do you find the interior angle formed by two intersecting chords?', back: 'It is half the sum of the two intercepted arcs.', src: 'f1904e91b224' },
  'amc10-0312': { front: 'How do you find the angle formed by two secants or tangents from outside a circle?', back: 'The angle is (larger arc − smaller arc)/2.', src: '586e8d463581' },
  'amc10-0313': { front: 'What is the distance between the centres when two circles are externally tangent?', back: 'The sum of the two radii.', src: '4419fbbaa4db' },
  'amc10-0314': { front: 'What is the distance between the centres when two circles are internally tangent?', back: 'The absolute difference of the two radii.', src: '8f1236d565bf' },
  'amc10-0315': { front: 'Why connect the centres to the point of tangency first in a tangent-circle problem?', back: 'The tangency point and the centres are collinear, or the radius is perpendicular there, which creates right angles and known distances.', src: '57f7ddd1b6f4' },
  'amc10-0316': { front: 'How do you find the area of a circular segment?', back: 'For a minor segment it is the sector area minus the triangle area; for a major segment it is sector plus triangle.', src: '0ba305015d3e' },
  'amc10-0317': { front: 'What split is usual for a regular polygon inscribed in a circle?', back: 'Join the centre to the vertices to form congruent isosceles triangles.', src: 'adf2bef8bc1f' },
  'amc10-0318': { front: 'What does a translation preserve?', back: 'Lengths, angles, areas and orientation.', src: '142e293b7ce9' },
  'amc10-0319': { front: 'What does a rotation preserve?', back: 'Lengths, angles and areas; distances to the centre of rotation are unchanged.', src: '28726797b4c8' },
  'amc10-0320': { front: 'What does a reflection preserve?', back: 'Lengths, angles and areas, but it reverses orientation.', src: 'ecc2b2ba385a' },
  'amc10-0321': { front: 'Under a dilation of factor k, how do lengths and areas change?', back: 'Lengths multiply by |k| and areas by k².', src: '5c4d1a41a96f' },
  'amc10-0322': { front: 'What is the coordinate rule for a reflection in the x-axis?', back: '(x,y)→(x,-y).', src: 'cd732a86e1cf' },
  'amc10-0323': { front: 'What is the coordinate rule for a reflection in the y-axis?', back: '(x,y)→(-x,y).', src: '7fbad7c6fecf' },
  'amc10-0324': { front: 'What is the rule for a 180° rotation about the origin?', back: '(x,y)→(-x,-y).', src: '26f22b3364e7' },
  'amc10-0325': { front: 'What is the rule for a 90° counterclockwise rotation about the origin?', back: '(x,y)→(-y,x).', src: 'afa6b809435a' },
  'amc10-0326': { front: 'What is the locus of points equidistant from two fixed points?', back: 'The perpendicular bisector of the segment joining them.', src: '0d24ec5cdfce' },
  'amc10-0327': { front: 'What is the locus of points equidistant from two intersecting lines?', back: 'The two angle bisectors.', src: 'f39caafa0004' },
  'amc10-0328': { front: 'What is the locus of points at a fixed distance from a fixed point?', back: 'A circle centred at that point.', src: 'e9240759f95e' },
  'amc10-0329': { front: 'What method usually solves the shortest broken-path problem?', back: 'Reflect one endpoint so the broken path straightens into a line.', src: '5ccc41ef6f7b' },
  'amc10-0330': { front: 'When a circle rolls without slipping, how does the distance travelled relate to the rotation?', back: 'The centre’s translation equals the arc length rolled, rθ.', src: '306af470eddb' },
  'amc10-0331': { front: 'When is it a good idea to use coordinates on a geometry problem?', back: 'When there are right angles, parallels, regular figures or distance conditions, and you can pick clean coordinates.', src: 'f75fb5eec0af' },
  'amc10-0332': { front: 'What is the volume of a rectangular box?', back: 'lwh.', src: '3f2094494da1' },
  'amc10-0333': { front: 'What is the surface area of a rectangular box?', back: '2(lw+lh+wh).', src: '616c7bdc65e3' },
  'amc10-0334': { front: 'What is the volume of a prism?', back: 'Base area × height.', src: '2be2efbf8034' },
  'amc10-0335': { front: 'What is the volume of a pyramid?', back: 'Base area × height / 3.', src: '617d6edbbca9' },
  'amc10-0380': { front: 'To get to town A you can take 3 buses or 4 trains (no transfer in between), why is the total 3+4 rather than 3×4?', back: '"Or / either…or" signals mutually exclusive cases, so add: 3+4=7. Only "first…then…" or "a choice must be made at every step" calls for multiplication.', src: 'b5b7a42eea13' },
  'amc10-0381': { front: '3 shirts with 4 pairs of pants — how many outfits are there? Why is it not 3+4?', back: 'It is completed in two steps (shirts first, pants second) and the number of choices at each step is fixed, so 3×4=12; only mutually exclusive "or" cases are added.', src: '758a471d5c62' },
  'amc10-0382': { front: 'From 5 people, how many times larger is "choose 3 to line up" than "choose 3 to attend a meeting"?', back: 'Lining up: 5·4·3=60, meeting: C(5,3)=10, so the first is 6=3! times the second (not a difference of 6). With the same set of objects: permutations when order matters, combinations when it does not - decide first whether order counts as different.', src: '7d1a59fff13b' },
  'amc10-0383': { front: 'How many ways are there for 5 people to line up? Why does 0! equal 1?', back: '5!=120; 0! means "arranging 0 objects out of 0", and there is only one empty arrangement, which also keeps C(n,n)=1 consistent with the formula.', src: 'df86339a6152' },
  'amc10-0384': { front: '8 contestants compete and the top 3 are taken (the places are distinct) — how many outcomes are there?', back: 'P(8,3)=8·7·6=336. Distinct places = ordered; once one is taken away there is one fewer left, so multiply the successive decreasing factors.', src: '3b3b8538c9ba' },
  'amc10-0385': { front: 'From 8 people, how many ways are there to choose 3 for duty?', back: 'C(8,3)=56. There is no order, so the 3! internal arrangements must be divided back out: 336÷6=56.', src: '3dc5b7f11ad2' },
  'amc10-0386': { front: 'You need to compute C(10,8) — what is the fastest way?', back: 'Use C(n,r)=C(n,n-r): C(10,8)=C(10,2)=45, replacing "choose 8" with "leave 2 unchosen".', src: 'f5fbe5250b52' },
  'amc10-0387': { front: 'Without a calculator, how do you get C(9,3) from C(8,·)?', back: 'Pascal\'s identity: C(9,3)=C(8,2)+C(8,3)=28+56=84, meaning the two cases "contains some particular element" and "does not contain it".', src: '23371380459c' },
  'amc10-0388': { front: 'How many subsets does a set of 6 elements have?', back: 'Each element is either "chosen or not chosen", two options, so 2^6=64 in total, which also equals ΣC(6,r)=1+6+15+20+15+6+1.', src: '7bbf1bf35b1f' },
  'amc10-0389': { front: 'How many different strings can the 11 letters of MISSISSIPPI form?', back: '11!/(4!4!2!)=34650: divide by the number of swaps among identical letters (4 S\'s, 4 I\'s, 2 P\'s), otherwise the same string is counted more than once.', src: 'e12b3d9661e4' },
  'amc10-0390': { front: '6 people sit around a round table (only rotations count as the same) — how many seatings are there?', back: '(6-1)!=120. A straight-line arrangement gives 6!=720, a difference of 6=the number of people; fixing one person as a reference reduces it to a straight-line arrangement.', src: 'a8d04903c9a9' },
  'amc10-0391': { front: 'For a 2-color 6-bead bracelet, counting only rotations gives 14; if reflections also count as the same, can you simply divide by 2?', back: 'You cannot get 7; the correct value is 13. Because some strings do not move under a reflection (such as left-right symmetric strings), dividing by 2 alone subtracts them too many times; you should count the "fixed configurations" for each symmetry operation and then average.', src: '0026964c3c1c' },
  'amc10-0392': { front: 'For rolling 3 dice, what is the fastest way to compute the probability of "at least one 6"?', back: 'Use the complement: 1-(5/6)^3=91/216≈0.421. Classifying directly into "exactly 1, 2, or 3 sixes" requires three cases and is easy to get wrong.', src: '257e567c7e2a' },
  'amc10-0393': { front: 'How many numbers from 1 to 100 are divisible by 3 or 5?', back: '33+20-6=47: subtract the multiples of 15 (6 of them), because they were counted once in each of the two sets.', src: 'e3226f044b57' },
  'amc10-0394': { front: 'How many numbers from 1 to 100 are divisible by 2 or 3 or 5?', back: '50+33+20-(16+10+6)+3=74: add the single sets, subtract the pairwise intersections, add the triple intersection, with alternating signs; missing the last term undercounts by 3 (the multiples of 30).', src: '64f5e60560d9' },
  'amc10-0395': { front: 'When distributing 5 identical balls to 2 people, are the two cases "the first person gets at least 1" and "the first person gets 0" enough?', back: 'Yes: the two cases are mutually exclusive and together make up everything. If you changed it to "the first person gets at least 1" and "the second person gets at least 1", they would overlap (such as 1+4) and be double counted.', src: 'f1f5f7ee4c8a' },
  'amc10-0396': { front: 'For 6 people at a round table, why can you fix 1 person as a reference?', back: 'Fixing one person removes the duplication caused by rotation, and the remaining 5 people are arranged in a line, giving (6-1)!=120. When you meet symmetry or adjacency restrictions, fixing a special object first often removes the duplication directly.', src: 'a3a0412b1680' },
  'amc10-0397': { front: '5 people line up and A and B must be adjacent — how many arrangements are there?', back: 'Bundle A and B into one block: 4!×2!=48. When "must be adjacent" appears, use the bundle method, and do not forget to multiply by the 2! inside the block.', src: '4288df0fafd0' },
  'amc10-0398': { front: '5 A\'s and 3 B\'s are arranged in a row with the B\'s required not to be adjacent to each other — how many ways are there?', back: 'Arrange the 5 A\'s first, forming 6 gaps, then choose 3 of them for the B\'s: C(6,3)=20. Elements of the same type are identical, so there is no further 3!; if the A\'s and B\'s were each distinct, you would also multiply by the internal arrangements.', src: '00d9c6390737' },
  'amc10-0399': { front: '10 identical candies are distributed to 3 children (someone may get none) — how many ways are there?', back: 'Stars and bars: C(10+3-1,3-1)=C(12,2)=66. Use this model when the items are identical and the boxes are distinct; only distinct boxes have labels.', src: '537748f0ea14' },
  'amc10-0400': { front: 'How many nonnegative integer solutions does x+y+z=10 have?', back: 'C(12,2)=66, the same thing as "10 identical balls distributed into 3 distinct boxes".', src: '1d426a2bac89' },
  'amc10-0401': { front: 'How many positive integer solutions does x+y+z=10 have?', back: 'Give each variable 1 first (using up 3), then distribute the remaining 7 freely: C(9,2)=36. Positive integer solutions require n≥k, otherwise there is no solution.', src: 'd0c7e8947bd8' },
  'amc10-0402': { front: 'For x+y+z=10 with each variable no more than 5, how many solutions are there? Can C(12,2) be applied directly?', back: 'No, you need inclusion–exclusion: 66-3·C(6,2)=66-45=21 (when some variable is ≥6, subtract 6 from it, leaving 4 to distribute to 3 variables). Two variables cannot exceed the bound at the same time, so nothing needs to be added back.', src: '7b2d97397a9b' },
  'amc10-0403': { front: 'Using the ten digits 0–9 (without repetition) to form three-digit even numbers, how many are there?', back: 'Classify by the last digit: when the last digit is 0, 9×8=72; when the last digit is 2/4/6/8, the first digit cannot be 0, so 4×8×8=256; 328 in total. The restrictions on the first and last digits must be handled separately.', src: 'f059244648ef' },
  'amc10-0404': { front: 'From 1–9, 3 digits are chosen and arranged into a strictly increasing three-digit number — how many are there?', back: 'Each chosen set has only one increasing arrangement, so it equals C(9,3)=84. If equal digits were allowed, it would become the multiset combination C(9+3-1,3).', src: '79f1fc60e048' },
  'amc10-0405': { front: 'A drawer holds socks in 4 colors; what is the fewest number you must take to guarantee a pair of the same color?', back: '5. In the worst case the first 4 are one of each color, and the 5th must be the same color as one of them (n+1 objects into n boxes).', src: '1896684e92fa' },
  'amc10-0406': { front: '8 people each shake hands with every other person once; counting in two ways gives what identity?', back: 'By person: each person shakes 7 times, 56 in total, and each handshake was shaken 2 times; by handshake: 2·C(8,2)=56, giving C(8,2)=28. Counting the same set of objects in two ways is double counting.', src: 'c02f8f80d249' },
  'amc10-0407': { front: 'Can 7 people each shake hands exactly 3 times?', back: 'No. The total degree 7×3=21 is odd, while each edge contributes 2, so the sum must be even (handshake theorem).', src: '22b73aed16eb' },
  'amc10-0408': { front: 'How many edges does a connected acyclic graph with 10 vertices have?', back: '9: V-1. A tree is connected and acyclic, and each added vertex adds exactly one edge.', src: 'a7b28b9ee169' },
  'amc10-0409': { front: 'On a grid of 4 columns and 3 rows, how many shortest paths go from the lower-left corner to the upper-right corner?', back: 'C(a+b,a)=C(7,4)=35: the path consists of 4 steps right and 3 steps up, so you only need to decide which steps go right.', src: '6609d431ce12' },
  'amc10-0410': { front: 'A staircase is climbed 1 step or 2 steps at a time; how many ways are there to go up 6 steps?', back: 'a_n=a_{n-1}+a_{n-2}, a_1=1, a_2=2, giving 13. Classifying by "how many steps the last move takes" is the most direct.', src: '15bca03e4ce1' },
  'amc10-0411': { front: 'When counting length-5 01 strings that have "no two adjacent 1s", what must the recursion state record?', back: 'Only whether the last bit is 0 or 1 (it decides whether the next step is restricted), 13 in total. The principle of state design is to keep only the least information needed to decide the next step.', src: '700b8573d2b1' },
  'amc10-0412': { front: 'After two diagonal squares are cut out of an 8×8 board, can it be tiled with 31 1×2 dominoes?', back: 'No. The board originally has 32 black and 32 white squares, and the two removed diagonal squares have the same color, leaving 30/32; but every domino must cover one black and one white, which requires the two colors to be equal in number.', src: '96efaede0ce6' },
  'amc10-0413': { front: '9, 5, 2 are written on a blackboard, and each time the largest number is replaced by the absolute value of the difference of the other two numbers — will this process go on forever?', back: 'No: (9,5,2)→(5,3,2)→(3,2,1)→(2,1,1)→(1,1,0), after which the state no longer changes. Because the new value |x-y| cannot exceed the previous maximum, the total is monotonically non-increasing, and it can only come to rest in a (k,k,0) form. Note that here you can only conclude "non-increasing and then stable"; saying "strictly decreasing" is wrong — (1,1,0) is a counterexample.', src: 'e1ac592c2cd5' },
  'amc10-0414': { front: 'To prove "n points have at most C(n,2) edges", which two steps must be written?', back: '① Construction: join every two points, attaining C(n,2); ② Upper bound: each edge corresponds to a pair of points, and the total number of point pairs is only C(n,2). The construction shows it can be attained and the upper bound proves it cannot be exceeded; only together do they count as an extremal proof.', src: '57e000237b45' },
  'amc10-0415': { front: 'Which of {2,3,5} and {1,4,6,9} is a sum-free set?', back: '{2,3,5} is not, because 2+3=5 is still in the set; {1,4,6,9} is, since the sum of any two numbers (which may be equal) is not in it. When reading the problem, first confirm whether x=y is allowed.', src: '726ba98aaccc' },
  'amc10-0416': { front: 'A 1×4 strip of cells is colored with the two colors black and white so that adjacent cells differ — how many ways are there?', back: '2. Once the first cell is fixed, the rest are uniquely determined; if the colors have labels ("black" and "white" are different), then the first cell has 2 choices and the answer doubles — in coloring problems, first ask whether the colors are equivalent.', src: 'e5567f059f15' },
  'amc10-0417': { front: 'To count "essentially different" 2×2 black-and-white colorings, what is the first step?', back: 'First list the set of operations regarded as the same (the 8 symmetries of the square: 4 rotations + 4 reflections), then look at which patterns they turn into one another. Without fixing the operation set first, the same pattern is counted repeatedly.', src: '8aac62267bde' },
  'amc10-0418': { front: 'Two colors are used to color the 4 vertices of a square (rotations and reflections both count as the same) — how many ways are there?', back: 'Average over the configurations each symmetry leaves fixed: (16+2+4+2+8+8+4+4)/8=6. The identity fixes 16; rotations by 90°/270° fix 2 each; rotation by 180° fixes 4; a reflection across either diagonal fixes 8 (the two vertices on the diagonal stay and the other two swap, giving 3 groups → 2³); a reflection across either midline fixes 4 (two pairs of vertices swap → 2²). AMC 10 uses this only when direct classification is very messy.', src: '1f5fb6d63d4f' },
  'amc10-0419': { front: '"Numbers from 1–100 that do not contain the digit 7" and "5 letters with two particular ones required not to be adjacent" — which uses inclusion–exclusion and which uses recursion?', back: 'The former is a global prohibition (the restrictions at each position are tangled up with one another), so use classification by digit or the complement; the latter is a local adjacency restriction, so use recursion or the gaps method. Global prohibition → inclusion–exclusion, local adjacency → recursion/gaps.', src: '51f754ebc42f' },
  'amc10-0420': { front: 'Two dice are rolled; what is the probability that the sum of the pips is 7?', back: '6/36=1/6: there are six favorable outcomes, (1,6)…(6,1). The two dice are ordered, so do not treat (1,6) and (6,1) as the same outcome.', src: '81abfeb3d4bf' },
  'amc10-0421': { front: 'Why can the 11 sums from 2 to 12 for the sum of two dice not be treated as equally likely?', back: 'The different sums correspond to different numbers of ordered outcomes (the sum 7 has 6, the sum 2 has only 1). "Favorable count / total count" holds only when the elementary outcomes are equally likely; confirm equal likelihood before applying the formula.', src: '4fbe97921fdb' },
  'amc10-0422': { front: '3 coins are tossed; what is the probability of "at least one head"?', back: '1-P(all tails)=1-1/8=7/8. When you see "at least", think first of the complementary event.', src: '9a9ccf867b05' },
  'amc10-0423': { front: 'Given P(A)=0.5, P(B)=0.4, P(A∩B)=0.2, what is P(A∪B)?', back: '0.5+0.4-0.2=0.7. Adding directly counts the intersection twice, so it must be subtracted once.', src: 'f85810ef26e0' },
  'amc10-0424': { front: 'A bag holds 3 red and 2 blue balls, and two are drawn without replacement; given that the first is red, what is the probability that the second is also red?', back: '2/4=1/2: the condition shrinks the sample space to the case "the first draw is red" and recounts there, which is equivalent to P(A∩B)/P(B)=(3/5·2/4)/(3/5).', src: 'a7979a7a639d' },
  'amc10-0425': { front: 'When two independent dice are rolled, can P(both 6) be multiplied out directly? What is the justification?', back: 'Yes: 1/36=1/6·1/6, which is exactly the definition of independence, P(A∩B)=P(A)P(B). General events must use the conditional probability P(A)P(B|A).', src: '4ba20853800a' },
  'amc10-0426': { front: 'Rolling a die once, are "getting 1" and "getting 2" mutually exclusive? Are they independent?', back: 'Mutually exclusive (they cannot happen at the same time), but not independent: when one happens the probability of the other becomes 0. Mutually exclusive events with positive probability are definitely not independent; the two terms cannot be used interchangeably.', src: '730826e5f189' },
  'amc10-0427': { front: 'For drawing two cards in succession from a 52-card deck, why is the probability that both are aces not (4/52)²?', back: 'Without replacement, the second draw has only 3 aces left among 51 cards: 4/52·3/51=1/221. The earlier result changes the sample space of the later one, so they are not independent.', src: '859ef8f99188' },
  'amc10-0428': { front: 'A shooter has hit rate 1/3; what is the probability of hitting at least once in 3 consecutive shots?', back: '1-(2/3)^3=19/27≈0.704. Only if the shots are independent can the probability of "all misses" be multiplied out directly.', src: '5f9102920aa6' },
  'amc10-0429': { front: 'A fair coin is tossed 5 times; what is the probability of exactly 3 heads?', back: 'C(5,3)(1/2)^5=10/32=5/16: first choose which 3 tosses are heads (a combination), then multiply by the probability of each order.', src: '9fe943417ccd' },
  'amc10-0430': { front: 'A box is chosen at random: box A (chosen with probability 1/3) has 3 red and 2 blue, box B has 1 red and 4 blue; what is the probability of drawing a red ball?', back: '1/3·3/5+2/3·1/5=1/3. Decompose the target probability by mutually exclusive and exhaustive cases and then weight them, provided that all paths that can produce the target outcome are listed first.', src: '9cee5c7bafa8' },
  'amc10-0431': { front: 'The prevalence is 1%, the test sensitivity is 99%, and the false positive rate is 5%; for a person who tests positive, what is the probability of actually having the disease?', back: '0.0099/(0.0099+0.0495)=1/6≈16.7%. The denominator includes all paths that produce a positive result (the false positives among the large number of healthy people); looking only at 99% would overestimate the answer to close to 1.', src: '97956e42fda0' },
  'amc10-0432': { front: 'Among 100 people there are 40 boys, of whom 10 wear glasses; given that the one chosen is a boy, what is the probability that he wears glasses?', back: '10/40=1/4. The condition shrinks the sample space from 100 people to 40, so both the numerator and the denominator change accordingly.', src: '078a985aa41d' },
  'amc10-0433': { front: '7 people line up at random; what is the probability that A stands exactly in the 3rd position?', back: '1/7. By symmetry, A is equally likely to fall in any position, so there is no need to compute 6!/7!.', src: '6f3674e25473' },
  'amc10-0434': { front: '5 people line up at random; what is the probability that A and B are adjacent?', back: '2/5. Bundling A and B into one block (2! ways) together with the other 3 people gives 4! arrangements, and dividing by 5! gives 2/5; for any n people it is 2/n.', src: '91a3b7660b3a' },
  'amc10-0435': { front: 'A point is chosen uniformly inside the unit square; what is the probability that its distance from the origin is less than 1?', back: 'π/4≈0.785: the favorable region is the quarter circle centered at the origin with radius 1. In an area model the probability equals the favorable area divided by the total area.', src: '6af13c542ca2' },
  'amc10-0436': { front: 'Is a point obtained by "first choosing the radius uniformly, then choosing the angle uniformly" the same as "a point chosen uniformly inside the disk"?', back: 'No. For a uniform point inside the disk the radial density is 2r (the further out, the larger the ring area), so choosing the radius uniformly makes the inner region overrepresented. The random mechanism determines the density, so the problem must first state clearly how the point is chosen.', src: '5125450ab486' },
  'amc10-0437': { front: 'A point is chosen uniformly inside a square; what is the probability that it falls exactly on a specified diagonal (or is exactly at distance 1)?', back: '0: the area of a line and the area of a circle are both 0. But the boundary is still used to divide regions (you must rely on it when finding "≥1" or "≤1"), so it cannot be ignored just because its probability is 0.', src: 'ac7bf7f12844' },
  'amc10-0438': { front: 'What is the expected value of rolling a fair die?', back: '(1+2+…+6)/6=3.5: sum each value multiplied by its probability, which is a weighted average.', src: '0a5edee844d1' },
  'amc10-0439': { front: 'Can a single roll of a die produce 3.5? Then what use is the expected value?', back: 'No. The expected value is a long-run average: after many rolls the average approaches 3.5. An expected value need not be a possible outcome.', src: 'ffce9856bdc9' },
  'amc10-0440': { front: 'Given E(X)=4, what is E(2X+3)?', back: '2·4+3=11. Constants can be pulled out and added, and there is no need at all to know the distribution of X.', src: '76bf2d0bb212' },
  'amc10-0441': { front: 'In the same deck, can the expected values of the first card\'s and the second card\'s value be added? Do they need to be independent?', back: 'Yes. E(X+Y)=E(X)+E(Y) holds for any random variables and does not require independence — this is the formula most easily misremembered as "requiring independence".', src: '60a37b09745c' },
  'amc10-0442': { front: 'How do you write the event "the die comes up even" as a random variable?', back: 'Let I=1 (comes up even) and I=0 (otherwise); then E(I)=P(even)=1/2. The expected value of an indicator variable is the probability of the event; that is its entire use.', src: '288bbd837c14' },
  'amc10-0443': { front: 'For X, the number of heads in 10 coin tosses, how do you find E(X) using indicator variables?', back: 'Write X=I_1+…+I_10, each E(I_i)=1/2, and adding gives 5. There is no need to find the distribution of X first.', src: '4105a158cd12' },
  'amc10-0444': { front: '5 balls are randomly placed into 5 labeled boxes (one ball per box); what is the expected number of "balls in the box of matching number"?', back: 'Set an indicator variable for each ball, with probability 1/5, and adding gives 5×1/5=1. For n objects in a random arrangement the expected number of fixed points is always 1.', src: '7d2c58c1195f' },
  'amc10-0445': { front: '10 balls are independently and randomly placed into 3 boxes; what is the expected number of non-empty boxes?', back: 'Set a "non-empty" indicator variable for each box: P(non-empty)=1-(2/3)^10, so the expectation is 3[1-(2/3)^10]≈2.95. The expected number of empty boxes is 3(2/3)^10.', src: 'e55e59673d26' },
  'amc10-0446': { front: 'A fair coin is tossed 6 times; what is the expected number of occurrences of the adjacent pair "HH"?', back: 'There are 5 adjacent positions in all, each with probability 1/4 of being HH, and adding gives 5/4=1.25. These positions are not independent, but linearity of expectation does not require independence.', src: 'b0775658dfe3' },
  'amc10-0447': { front: 'For independent trials with success probability 1/4 each, how do you compute the expectation of the number of trials X needed for the first success with the tail sum?', back: 'E(X)=Σ_{k≥1}P(X≥k)=Σ(3/4)^{k-1}=1/(1-3/4)=4, consistent with 1/p for the geometric distribution. The tail sum suits variables that take positive integer values.', src: 'bb8a36be16b0' },
  'amc10-0448': { front: 'Two dice are rolled and the larger value is taken; what is the expected value?', back: 'Compute the cumulative first: P(M≤m)=(m/6)², differencing gives P(M=m)=[m²-(m-1)²]/36, and summing gives 161/36≈4.47. To find the expectation of a maximum, computing the "≤" cumulative first is easier.', src: '641fd5e77542' },
  'amc10-0449': { front: 'The success probability is always 1/3 and the trials are independent; how many trials does the first success need on average?', back: '1/p=3: write E=1+failure probability·E and it can be solved. If the success probability changes with the round, you must switch to the state equation E_s=1+ΣP(s→t)E_t.', src: 'dff5699a8558' },
  'amc10-0450': { front: 'A coin is tossed until the sequence "head then tail" appears; how many tosses are needed on average? How do you write the first step of the analysis?', back: 'Set unknowns by the prefix already matched: p_∅=1+½p_H+½p_∅, p_H=1+½p_H (tossing another head still stays at H), which solves to an average of 4 tosses starting from the empty state. The key is to classify by "which prefix is currently matched".', src: 'e7064852c94e' },
  'amc10-0451': { front: 'For a fair random walk with endpoints 0 and 3, starting from 1, what is the probability of reaching 3 first, and what do you write in the first step?', back: 'First write the absorbing boundaries P(0)=0, P(3)=1, then write the interior equation P(i)=½P(i-1)+½P(i+1), which solves to P(1)=1/3. Without writing the boundaries, the equations cannot be solved for a definite value.', src: '21c1358bf879' },
  'amc10-0452': { front: 'For a fair one-dimensional random walk between two absorbing endpoints, how does the probability of reaching the right endpoint first change with the starting point?', back: 'It changes linearly (for a starting point i between 0 and N). Once the endpoint values are determined you can interpolate directly, without solving the equations point by point.', src: '19d6b2b73d03' },
  'amc10-0453': { front: 'For a fair random walk from 0 to 8, starting from 5, what is the probability of reaching 8 first?', back: 'i/N=5/8. This is a direct application of the linear conclusion above: the further right the starting point, the easier it is to hit the right end first.', src: 'a8d91950c4fe' },
  'amc10-0454': { front: 'After solving the probabilities of the various states by recursion, what three things must be checked?', back: '① Every probability lies between 0 and 1; ② the values at the absorbing boundaries match the problem (success=1, failure=0); ③ whether the states cover all possibilities — a missing state makes the equations unsolvable or makes the answer too large.', src: '2ddd4361359f' },
  'amc10-0455': { front: 'Can P(A∩B) be written directly as P(A)P(B)?', back: 'Only when they are independent. In general use the conditional multiplication P(A∩B)=P(A)P(B|A); multiplying directly for dependent events (such as rain on two consecutive days) gives a wrong result.', src: 'e1ca1291e29c' },
  'amc10-0456': { front: '3 balls are randomly placed into 2 boxes; do the two distributions (3,0) and (1,2) have the same probability?', back: 'No. If the balls choose boxes independently of one another, (3,0) has 2 outcomes and (1,2) has 6, with probabilities 2/8 and 6/8 respectively. Count by the equally likely choice of each object; the "distribution of counts" cannot be treated as equally likely.', src: '6ca8efd34b5e' },
  'amc10-0457': { front: 'For two dice, which is more likely to appear, the sum 7 or the sum 12?', back: 'The sum 7 has 6 ordered outcomes and the sum 12 has only 1, with probabilities 6/36 and 1/36. The sums themselves are not equally likely; the middle sums are more likely to appear.', src: '74bc56bcb67a' },
  'amc10-0458': { front: 'How many ways are there to split 8 different cards into three piles of 3, 3, and 2 (the three piles have labels)?', back: '8!/(3!3!2!)=560: first decide the members of each pile, then divide out the order inside each pile (a pile is unordered).', src: '0dc6c3d641de' },
  'amc10-0459': { front: 'When 6 people are split into two teams of 3 each, why divide by an extra 2!?', back: 'When the two teams have names (team A/team B) it is C(6,3)=20; when they have no names, swapping the two teams gives the same split, so divide by another 2!=2 to get 10. Whether the boxes have labels determines whether to deduplicate.', src: '5190bcd9bbdf' },
  'amc10-0460': { front: 'In how many ways can 6 people be split evenly into 3 groups (2 people each, no names for the groups)?', back: 'First count with labeled groups: C(6,2)C(4,2)C(2,2)=90, then divide by 3!=6 to get 15. Divide by the factorial of the number of groups only when the group sizes are equal.', src: '199f1093f870' },
  'amc10-0461': { front: 'What is the difference between "splitting 3 into a sum of several positive integers" and "the nonnegative integer solutions of x+y=3"?', back: 'Integer partitions do not count the order of the summands: 3 has only three, 3, 2+1, and 1+1+1; equation solutions have labeled variables and count order: x+y=3 has four, (0,3)(1,2)(2,1)(3,0).', src: '1b7c1f9c4d4d' },
  'amc10-0462': { front: 'How many inversions does the permutation 3142 have?', back: '3 pairs: 3>1, 3>2, 4>2. The most common way to count is to count one by one "how many elements before it are larger than it" and then add.', src: 'b5009762bc35' },
  'amc10-0463': { front: 'When two adjacent elements in a permutation are swapped, how does the parity of the number of inversions change?', back: 'It changes by exactly 1 (the relative order of these two elements is reversed, while their order relative to all other elements is unchanged), so the parity flips. This is exactly the source of "an adjacent swap changes the parity of a permutation".', src: '67a1bd19cad9' },
  'amc10-0464': { front: 'How many games are there in all in an 8-person round-robin (every two people play one game)?', back: 'C(8,2)=28: a game corresponds to a pair of players, and the order does not matter.', src: '5e297845a14a' },
  'amc10-0465': { front: '6 points on a circle are joined in pairs (no three chords are concurrent); how many intersection points are there inside the circle?', back: 'C(6,4)=15: each intersection point corresponds uniquely to 4 points (their two diagonals intersect). Missing "every 4 points determine one intersection point" leads to double counting.', src: '7444e6a80334' },
  'amc10-0466': { front: 'At most how many regions does the n-th line in general position divide the plane into? What about 5 lines?', back: 'The n-th line is cut by the existing n-1 intersection points into n segments, which adds n regions: the number of regions is 1+n(n+1)/2, which is 16 when n=5. It must be guaranteed to be in general position (no parallels, no three lines concurrent).', src: '6b0fbfda67a8' },
  'amc10-0467': { front: 'In how many ways can 4 letters all be put into the wrong envelopes?', back: 'Derangement D_4=9: by inclusion–exclusion, 4!-C(4,1)3!+C(4,2)2!-C(4,3)1!+C(4,4)0!=24-24+12-4+1=9.', src: 'b3a883edb65c' },
  'amc10-0468': { front: 'Given D_3=2 and D_4=9, what is D_5?', back: 'D_n=(n-1)(D_{n-1}+D_{n-2})=4×(9+2)=44. The recursion is faster than inclusion–exclusion; use the recursion when n is larger.', src: '34deafd4db6d' },
  'amc10-0469': { front: 'How many valid bracket sequences can 4 pairs of brackets form?', back: 'The Catalan number C_4=14, equal to the number of paths where "in the prefix the closing brackets are never more numerous than the opening brackets". The recognition signal is exactly this "prefix that never crosses the boundary", and it is not in the AMC 10 must-memorize scope.', src: '954cb4968352' },
  'amc10-0470': { front: 'Among all subsets of {1,2,3}, at most how many can be taken in a family of sets such that "no two contain each other"?', back: 'The middle layer is the largest, such as {1},{2},{3}, 3 in all (equal to C(3,1)=C(3,2)). The typical answer to an antichain problem is the middle layer, and double counting can prove it is optimal.', src: 'e6b197599a70' },
  'amc10-0471': { front: 'In a 3-person competition ties are allowed; how many ways are there to rank them?', back: '13: classify by the number of tie blocks - 1 block gives 1 way (all tied), 2 blocks give 3×2=6 ways, 3 blocks give 3!=6 ways, and 1+6+6=13 in all. You must first state whether the ranks after a tie are skipped.', src: '85da5ec61078' },
  'amc10-0472': { front: 'Coloring a 5-cell strip with the requirement that adjacent cells differ, what does the recursion state record?', back: 'Only the color of the previous cell (and whether it is the same as the cell before that); there is no need to save the history of the whole strip. The principle of state design is to keep only the least information needed to decide the next step.', src: 'b99d55b2c301' },
  'amc10-0473': { front: 'Among 10 products 3 are defective; 4 are chosen at random — what is the probability that exactly 1 is defective?', back: 'C(3,1)C(7,3)/C(10,4)=105/210=1/2. Drawing without replacement uses the hypergeometric distribution: the numerator chooses the defective and the good items separately, and the denominator chooses from all of them.', src: '8d17327ad526' },
  'amc10-0474': { front: '5 different balls are independently and randomly placed into 3 boxes; what is the probability that "one box has 2, another box has 2, and the third box has 1"?', back: 'First choose which box holds 1 (3 ways); each such distribution has 5!/(2!2!1!)=30 outcomes, 90 in all; dividing by 3^5=243 gives 90/243≈0.370.', src: '6db7a74ec5e4' },
  'amc10-0475': { front: 'One divisor of 12 is chosen at random; what is the probability of choosing one greater than 6?', back: 'The divisors are 1,2,3,4,6,12, 6 in all, and only 12 is greater than 6, so the probability is 1/6. What is uniform is the items in the divisor list; uniformity cannot be assumed over the numerical range.', src: '62dffd9e7d88' },
  'amc10-0476': { front: 'Given P(A|B_i) for the various cases, how do you find P(A)?', back: 'For mutually exclusive and exhaustive B_i use the law of total probability P(A)=ΣP(A|B_i)P(B_i). The prerequisite is that the B_i are pairwise mutually exclusive and their union is the whole space; missing one case undercounts.', src: '74f94cd5a3fc' },
  'amc10-0477': { front: 'Given the conditional expectations for the various cases, how do you combine them into E(X)?', back: 'Use the stratified formula E(X)=ΣE(X|B_i)P(B_i), a weighted average by the case probabilities; the prerequisite is likewise that the cases are mutually exclusive and exhaustive.', src: 'beef268be287' },
  'amc10-0478': { front: 'When does E(XY)=E(X)E(Y) hold?', back: 'Only when X and Y are independent. In general you must compute with the joint distribution; when they are not independent, the correlation pushes the expectation of the product off.', src: 'de5e39b83d62' },
  'amc10-0479': { front: 'What are the definitional formula and the computational formula for variance?', back: 'Var(X)=E[(X-E(X))²]=E(X²)-[E(X)]². The computational formula is faster, but both uses require linearity of expectation.', src: '166a4d08b710' },
  'amc10-0480': { front: 'What are the expected value and the variance of an indicator variable with success probability p?', back: 'E=p, Var=p(1-p) (because X²=X). The variance is largest when p=1/2, equal to 0.25.', src: '6dca31eff881' },
  'amc10-0481': { front: 'To find the expected value of a minimum M, how do you write it with the tail sum?', back: 'E(M)=Σ_{k≥1}P(M≥k), and P(M≥k) is usually easier to compute than P(M=k) ("all variables are ≥k"). You can also list the distribution of M directly.', src: 'f99670987807' },
  'amc10-0482': { front: 'How do you write the expected-number-of-steps equation for an absorbing random process?', back: 'For non-terminal states E_s=1+ΣP(s→t)E_t, and terminal states are 0 (or take the value required by the problem). The 1+ stands for this step itself; do not leave it out.', src: '4598242355d3' },
  'amc10-0483': { front: 'In a random walk, what do you do when two states have exactly the same future behavior?', back: 'Merge them into the same unknown, and the number of equations immediately decreases. The criterion is "the future transition probability distributions are the same", not that the positions merely look symmetric.', src: 'c7934646eb3b' },
  'amc10-0484': { front: '4-person single-elimination tournament: A plays B in the first round (A wins for sure), the other match is C versus D (C wins for sure), and in the final A versus C, A\'s win rate is 1/2. What is the probability that A wins the title?', back: '1×1×1/2=1/2: along "the next opponent", multiply the current round\'s probability by the subsequent conditional probability round by round. If the opponent is uncertain, you must also weight and add by the probability of each opponent appearing.', src: '257c2561173f' },
  'amc10-0485': { front: 'Once "final success" has been observed, why must the probabilities of some early branches be revised downward?', back: 'Because the branches differ in their probability of leading to success: P(branch|success)=P(success|branch)P(branch)/P(success), and low-yield branches are pushed down. This kind of backward inference from the outcome must be reweighted with Bayes; the prior proportions cannot be carried over.', src: '1b32054607e8' },
  'amc10-0486': { front: '"3 times a number is 14 less than 5 times the number" — what is the first step?', back: 'Let the number be x and translate each sentence into an equation: 3x=5x-14, which gives x=7. In word problems, define the variable and write down the units first, then translate sentence by sentence — do not rush into arithmetic.', src: '15fbc2c48ead' },
  'amc10-0487': { front: 'The problem says "the figure is not drawn to scale," and two sides in the figure look equally long. Can you conclude they are equal?', back: 'No. Redraw a clear sketch and mark the givens, equal lengths, parallels, and right angles on it; go by the markings, not by eye. An unmarked angle cannot be treated as 90°.', src: '4697aeb40773' },
  'amc10-0488': { front: 'Can the numbers 1 through 9 be split into two groups so that the two group sums are equal?', back: 'Impossible. The total 45 is odd, while equal group sums would force the total to be even — this is the invariant (the parity of the sum).', src: 'e6b0b7809cb5' },
  'amc10-0489': { front: 'For positive integers with a+b=10, how does symmetry make maximizing ab easier?', back: 'Swapping a and b changes neither the condition nor the target, so try the symmetric point a=b=5 first: it gives 25, and then check that it really is the maximum. Symmetry gives a candidate, not a guarantee: the equally symmetric a²+b² under a+b=10 is in fact maximized at (1,9).', src: 'b224f8b1a707' },
  'amc10-0490': { front: 'Among 5 positive integers, the sum of any three is at most 10. What is the largest possible value of the biggest number?', back: '8. Use the extreme principle: to make the largest number M as large as possible, take the other 4 numbers as small as possible, 1,1,1,1, so 1+1+M≤10 gives M≤8, and (8,1,1,1,1) attains it.', src: '927d87c90034' },
  'amc10-0491': { front: 'When proving that √2 is irrational, why do we assume from the start that p/q is already in lowest terms?', back: 'Proof by contradiction: assume √2=p/q with p,q coprime; this gives p²=2q², so p is even and therefore q is even too, contradicting coprimality. Taking "lowest terms" first is what makes the contradiction land in the final step.', src: 'fee315420d21' },
  'amc10-0492': { front: 'How do you prove that at most 5 cells of a 3×3 grid can be chosen with no two of them adjacent?', back: 'Upper bound: pair 8 of the cells into 4 adjacent pairs (for example (1,1)-(1,2), (1,3)-(2,3), (3,3)-(3,2), (3,1)-(2,1)); each pair contributes at most 1 chosen cell, and adding the remaining center cell gives ≤4+1=5. Construction: the four corners plus the center, exactly 5. A proof is complete only when a construction is produced and an upper bound shows you cannot exceed it.', src: '0b58ee71348d' },
  'amc10-0493': { front: 'A sequence starts 1, 2, 4, 8, 16. Must the next term be 32?', back: 'Not necessarily. The number of regions cut out by connecting n points on a circle pairwise is exactly 1, 2, 4, 8, 16, but the 6th term is 31. Small cases are only for spotting a pattern or finding counterexamples; they cannot replace a proof.', src: '3a39a35baacb' },
  'amc10-0494': { front: 'For the equation 4^x=8, how do you settle it quickly using the answer choices?', back: 'When the choices are simple, substitute them back directly: 4^{3/2}=8, so only 3/2 works. When solving backwards is messy but the choices are clean, substituting the answers is a legitimate time-saver — but you must actually plug in every choice one by one.', src: '8eaf00f484e5' },
  'amc10-0495': { front: 'For deciding a polynomial identity with parameters, what can substituting special values do, and what can it not do?', back: 'It can quickly eliminate wrong choices (try x=0, 1, -1), but it cannot prove the identity — a proof requires simplifying to the same expression, or covering all values.', src: '55b535543586' },
  'amc10-0496': { front: 'In an area problem, what does it mean when a choice is a quantity like 3π cm?', back: 'It can be eliminated outright: an area must be in units of length squared. Dimensional analysis is the cure for unit or degree errors.', src: 'f9a43b6fb11b' },
  'amc10-0497': { front: 'When all the conditions are quadratic, why may you set some quantity equal to 1?', back: 'When every term has the same degree (homogeneity), the whole expression scales by a common factor and any ratio answer is unchanged, so you often set some sum or length to 1 to simplify. Note that this changes the numerical value of the sum itself, so it is safe only for targets of the "ratio" kind.', src: 'd7562752566c' },
  'amc10-0498': { front: 'For the minimum of x+1/x (x>0), how do you do two things at once?', back: 'Lower bound: x+1/x≥2√(x·1/x)=2; equality case: x=1 attains 2. So the minimum is 2. Giving only the lower bound without an equality example leaves the answer incomplete.', src: '8e7cddc680e2' },
  'amc10-0499': { front: 'What should (x-3)²+(y-4)² make you think of?', back: 'Read it as the square of the distance from the point (x,y) to (3,4). Distance radicals, sums of squares, absolute values, or a fixed sum or product are the signals for turning an algebra problem into geometry.', src: '0cd36753b86b' },
  'amc10-0500': { front: 'A regular hexagon is inscribed in the unit circle. What is its side length, and what is the fastest way to get it?', back: 'Use coordinates, or split it into 6 equilateral triangles: the radius is the side length, so the side is 1. Plenty of right angles, parallels, ratios, or regular transformations are the signals for turning a geometry problem into algebra.', src: '61dda4896304' },
  'amc10-0501': { front: 'One problem can be done by coordinates or by similar triangles. How do you choose?', back: 'Pick the route with fewer conditions, shorter computation, and cleaner checking: coordinates are steady when there are many right angles and regular figures, while similarity is faster when ratios are dense. Once both are laid out, compare which one has fewer intermediate steps.', src: 'e1113b7b9e14' },
  'amc10-0502': { front: 'A problem asks for "the number of whole numbers less than 4". Does 0 count?', back: 'Yes: whole number usually includes 0, so the answer is 4 (0,1,2,3) rather than 3; integer is the word for "integer" in general. Neither can be taken for granted — go by the problem\'s definition.', src: 'de6e5cb01c82' },
  'amc10-0503': { front: 'How many "positive divisors of 6" are there?', back: '4: 1, 2, 3, 6. "Positive" does not include 0, and 0 is not a divisor of any positive integer.', src: 'af7fda2fb86e' },
  'amc10-0504': { front: 'Three-digit numbers are formed from the digits 1, 2, 3. What difference does it make if the problem says distinct?', back: 'With distinct, digits cannot be reused, so there are only 3!=6; if repetition is allowed there are 3³=27. When you see distinct, first strike out the counts that reuse digits.', src: '880285c6d400' },
  'amc10-0505': { front: 'How do you compute the probability for "at least 2 of the 5"?', back: 'At least 2 means ≥2. For 5 tosses of a fair coin, at least 2 heads: 1-P(0)-P(1)=1-1/32-5/32=13/16. When you see at least, think of the complementary event first.', src: 'c3c7836e20c4' },
  'amc10-0506': { front: 'What do no more than 3 and no less than 3 translate to?', back: 'No more than means ≤3; no less than means ≥3. They are the at most / at least pair — do not write the two the wrong way round.', src: '25b7ee0c529b' },
  'amc10-0507': { front: '"three consecutive integers have sum 42" — what are the three numbers?', back: '13, 14, 15 (the middle number = 42/3 = 14). Consecutive means adjacent numbers differ by 1, and letting the middle number be n is the fastest way.', src: 'fe12312b2168' },
  'amc10-0508': { front: 'How many factors does 12 have? How many multiples of 12 are less than 50?', back: 'There are 6 factors: 1,2,3,4,6,12; there are 4 multiples less than 50: 12,24,36,48. Factor/divisor means a divisor, multiple means a multiple, and the two point in opposite directions.', src: '7a003cc588cb' },
  'amc10-0509': { front: 'What range must a remainder satisfy? What is the remainder when -1 is divided by 7?', back: 'A remainder satisfies 0≤r<m, so the remainder when -1 is divided by 7 is 6, not -1. When you write n=7q+r, do not forget this range.', src: '5985a682dbad' },
  'amc10-0510': { front: 'A number is chosen uniformly at random from 1 to 10. What is the probability that it is prime?', back: 'Chosen uniformly at random means every outcome is equally likely. The primes are 2,3,5,7, 4 of them, so the probability is 4/10=2/5.', src: 'c4569f1afbad' },
  'amc10-0511': { front: 'How do you compute "two draws, without replacement, both red"? The bag holds 3 red and 2 blue.', back: '3/5·2/4=3/10. Without replacement means the ball is not put back, so the counts change for the second draw, and the two draws are not independent.', src: 'a07e54782d0d' },
  'amc10-0512': { front: 'Does expected number mean "the number most likely to occur"?', back: 'No. The expected value of one die roll is 3.5, and 3.5 is not a possible outcome at all; the expectation is the long-run average. The expected sum of two dice is 7, which happens to be the most likely value as well — that is only a coincidence.', src: '62a9b4949a50' },
  'amc10-0513': { front: 'What are tangent, secant, and chord? A secant runs 4 units outside the circle and its chord inside is 9 long; how long is the tangent drawn from the same point?', back: 'In order: tangent, secant, chord. Tangent-secant theorem: tangent² = outer segment × the WHOLE secant; the whole secant is 4+9=13, so t²=4×13=52 and t=2√13≈7.21. The usual mistake is to treat the inner chord 9 as the whole secant and forget the part outside the circle.', src: '7cb2415c11a0' },
  'amc10-0514': { front: 'What is the difference between circumcircle and incircle? What are the two radii for a 3-4-5 right triangle?', back: 'The circumcircle passes through the vertices, while the incircle is tangent to all three sides. For a 3-4-5 right triangle the circumradius is 5/2=2.5 and the inradius is (3+4-5)/2=1.', src: 'f63bc14c21cd' },
  'amc10-0515': { front: 'A segment has endpoints (0,0) and (4,0). What is its perpendicular bisector?', back: 'The perpendicular bisector is x=2. Finding a perpendicular bisector means finding the set of points equidistant from the two endpoints, which is often used to locate a circumcenter or a circle center.', src: 'f81ecc785664' },
  'amc10-0516': { front: 'What are the centroid, incenter, circumcenter, and orthocenter?', back: 'Centroid (intersection of the three medians), incenter (intersection of the angle bisectors, the center of the incircle), circumcenter (intersection of the perpendicular bisectors, the center of the circumcircle), orthocenter (intersection of the three altitudes). For a 3-4-5 right triangle the distance from the incenter to the hypotenuse is 1.', src: 'a434d7b010d8' },
  'amc10-0517': { front: 'How do similar and congruent differ? If the similarity ratio is 1:2, what is the area ratio?', back: 'Similar allows scaling, while congruent means identical in both shape and size. With similarity ratio 1:2 the area ratio is 1:4 and the volume ratio is 1:8 — scale by squares and cubes.', src: '7d4467d06500' },
  'amc10-0518': { front: 'What does "a figure is inscribed in a circle" mean? What can you conclude from it?', back: 'All the vertices of the figure lie on the circle. It follows that an angle subtended by a diameter is always 90°, which is the most common use.', src: '670c49610ed4' },
  'amc10-0519': { front: 'What does "a circle is inscribed in a polygon" mean? What is the radius when the equilateral triangle has side 6?', back: 'The circle is tangent to every side of the polygon. The inradius of an equilateral triangle is r=a√3/6=√3. Do not mix up the two directions of inscribed in: vertices on the circle versus the circle tangent to the sides.', src: '6b1869708689' },
  'amc10-0520': { front: 'Besides computing the bound, what else must you confirm for "the maximum possible value"?', back: 'You must also confirm that the bound can be attained by a legal object. For example, for a triangle with integer sides and perimeter 12, the largest side is at most 5 ((5,4,3) is legal, while 6 would violate 6<6).', src: '9b267baac7d0' },
  'amc10-0521': { front: 'What does "not necessarily drawn to scale" warn you about?', back: 'You cannot judge lengths, angles, or intersection positions by eye; everything follows the markings and the conditions, which is also the direct reason to redraw any figure problem first.', src: '3c585e976c90' },
  'amc10-0522': { front: 'What is the structure of the full AMC 10 exam?', back: '25 five-choice questions, usually 75 minutes, averaging 3 minutes per question; the rules for the current year still need to be confirmed on the official MAA website.', src: '1065787cb567' },
  'amc10-0523': { front: 'What is the goal of the first pass?', back: 'Bank the problems you are sure you can do first; do not aim to finish everything. At an average of 3 minutes per problem, letting one hard problem swallow 10 minutes means deliberately giving up the next three.', src: '88f642ab9075' },
  'amc10-0524': { front: 'When should you temporarily skip a problem?', back: 'When after about 2–3 minutes there is still no clear progress, the computation has already run away from you, or you have not yet identified the model. Skipping is a strategy, not giving up; on returning, it often becomes obvious at a glance.', src: '9d254de038f7' },
  'amc10-0525': { front: 'What should you check before filling in the answer sheet?', back: 'Whether the problem numbers and choices are misaligned, whether any entire problem was left unmarked, and whether skipped problems are handled according to your plan. These errors cost as much as a wrong calculation, yet they are entirely avoidable.', src: '65b4dda5acfe' },
  'amc10-0526': { front: 'What three checks should a numerical answer pass?', back: 'Sign, order of magnitude, and units and range. Getting a negative value for a length, or 0.3 for a number of people, both mean some earlier step was wrong.', src: '35e738a06a7e' },
  'amc10-0527': { front: 'What sanity checks should a geometry answer pass?', back: 'Lengths are positive, angles lie in the correct range, a triangle satisfies that the sum of two sides exceeds the third, and an area does not exceed its container. For example, a leg coming out as 6 while the hypotenuse is 5 must be wrong.', src: 'c5371899b2cc' },
  'amc10-0528': { front: 'What range must a probability answer fall in? Is the expected value subject to that range too?', back: 'A probability must be between 0 and 1; getting 1.2 or -0.1 means checking back immediately. The expected value is not subject to this restriction — it can be 3.5 or even any real number.', src: '8c77b1256d83' },
  'amc10-0529': { front: 'What should you check last on an integer problem?', back: 'The positive or nonnegative requirement, divisibility, parity, the range of values, and whether anything was double-counted. If the problem asks for positive integer solutions and you get 0 or a negative number, go back and look at the boundary.', src: '17ee8d231e6e' },
  'amc10-0530': { front: 'Into which categories should wrong problems be filed, at minimum?', back: 'Knowledge gaps, model recognition, computational slips, misreading the problem, and time management. The category decides the remedy: model recognition is fixed with recognition cards, while computational slips can only be fixed with process and double-checking.', src: 'bceee602f321' },
  'amc10-0531': { front: 'Why is reading the answer not enough when retesting a wrong problem?', back: 'Understanding the answer does not mean you can independently rebuild the solution. You have to redo it with the book closed and say out loud which method the first sentence of the problem triggered, otherwise you will still stall at the start next time.', src: 'e6eb5ea0ddd7' },
  'amc10-0532': { front: 'What retest intervals are recommended?', back: 'About once at 48 hours, once at 7 days, and once at 21 days, then adjust according to how much you forget. Intervals that are too tight produce short-term memory, and ones that are too loose amount to learning from scratch.', src: 'be590ff29e6e' },
  'amc10-0533': { front: 'What is the core mathematical scope of the AMC 10?', back: 'Elementary algebra, elementary geometry, elementary number theory, counting and probability, and combined problems that mix them. Tools outside the scope are not forbidden — you simply do not need to learn them first.', src: '670609fb42a7' },
  'amc10-0534': { front: 'Is calculus part of the required AMC 10 scope?', back: 'No. Completing the square, AM-GM, or symmetry is enough to find extrema; the derivative is only an optional shortcut.', src: 'bc4fee64ca1b' },
  'amc10-0535': { front: 'Is trigonometry part of the official core scope?', back: 'No. What is needed is the values at special angles (such as sin30°=1/2) and geometric relationships; you do not need the full set of trigonometric identities and triangle solving.', src: '204340b763e4' },
  'amc10-0536': { front: 'Should complex numbers be treated as a priority topic?', back: 'No. It is not priority material for AMC 10 preparation, unless you personally want to go further.', src: 'bc2d83c62ebd' },
  'amc10-0537': { front: 'Should advanced inequalities be learned before the basic methods?', back: 'No. The order is AM-GM, Cauchy, Titu, completing the square, the triangle inequality, and equality-case checking; first become fluent in the equality conditions of the basic methods.', src: '5a2942da6453' },
  'amc10-0538': { front: 'Must you master Burnside and generating functions?', back: 'No. They are only enrichment tools for a small number of hard symmetry/counting problems; the main body still relies on casework, inclusion–exclusion, and recurrence.', src: 'f47a96a28d0e' },
  'amc10-0539': { front: 'Does low frequency over the past five years mean it will not be tested?', back: 'No. Frequency is only used to allocate training time; it cannot be used to cut down the syllabus or to guess what will appear.', src: 'b7fcb2fd7942' },
  'amc10-0540': { front: 'Can drilling flashcards alone replace doing complete problems?', back: 'No. Cards handle memory and recognition, while real problems handle modeling, computation, and time pressure; neither can be missing.', src: '26b3fc281572' },
  'amc10-0541': { front: 'What counts as a proposition?', back: 'A declarative sentence whose truth or falsity can be determined unambiguously. "3 is odd" is a proposition, while "please close the door" and "x+1=2" (containing a free unknown) are not.', src: '38c12ab2f410' },
  'amc10-0542': { front: 'How do you write the negation of a proposition P?', back: 'Write it as "P does not hold", and it must cover every case other than P. Over the integers, the negation of "n is even" is "n is odd", not "n is negative".', src: 'cbfdfea215f4' },
  'amc10-0543': { front: 'What is the negation of "every object satisfies P"?', back: '"There exists at least one object that does not satisfy P". The negation of "all primes are odd" is "there exists a prime that is not odd" (2), not "all primes are not odd".', src: '47e21c4e8796' },
  'amc10-0544': { front: 'What is the negation of "there exists at least one object satisfying P"?', back: '"Every object fails to satisfy P". The negations of an existential and of a universal swap with each other, and the quantifier must never be changed in only the second half of the sentence.', src: 'a2fe36a13e9c' },
  'amc10-0545': { front: 'When is the implication P→Q false?', back: 'Only when P is true and Q is false. "n is a multiple of 4 → n is even" is true; conversely, "n is even → n is a multiple of 4" is false at n=2.', src: '43662874bc41' },
  'amc10-0546': { front: 'What is the converse of P→Q? Is it equivalent to the original proposition?', back: 'The converse is Q→P, and it is not necessarily equivalent. The pair of examples above is exactly that case: one is true while its converse is false.', src: '94fb313d146c' },
  'amc10-0547': { front: 'What is the contrapositive of P→Q? Is it equivalent to the original proposition?', back: 'The contrapositive is "not Q → not P", which is equivalent to the original. "n is not even → n is not a multiple of 4" and "n is a multiple of 4 → n is even" are true or false together.', src: 'd140b3167444' },
  'amc10-0548': { front: 'What does "P is a sufficient condition for Q" mean?', back: 'It means P→Q. "n is a multiple of 4" is a sufficient condition for "n is even" — having it is enough, and the statement may still hold without it.', src: 'd78acb6a01e7' },
  'amc10-0549': { front: 'What does "P is a necessary condition for Q" mean?', back: 'It means Q→P. "n is even" is a necessary condition for "n is a multiple of 4" — if it fails, the conclusion definitely fails.', src: '2f00811bdb61' },
  'amc10-0550': { front: 'What must be proved for "if and only if"?', back: 'Both directions must be proved. For "n is even ⟺ n² is even" you must prove that n even implies n² even, and also that n² even implies n even.', src: '139a180dfa1f' },
  'amc10-0551': { front: 'What can one counterexample disprove?', back: 'It can disprove universal statements of the "all … are …" or "necessarily …" kind. "All primes are odd" is disproved by the single counterexample 2.', src: 'df2f1fcc8b45' },
  'amc10-0552': { front: 'Can one example prove "possible"? Can it prove "always"?', back: 'It can prove "there exists / possible" (for instance 1×2×3=6 shows that there exist three consecutive integers whose product is divisible by 6), but it cannot prove "always" — that requires a general argument.', src: '10733e385187' },
  'amc10-0553': { front: 'What is a robust method for truth-teller/liar problems?', back: 'Give each person a truth variable, write each sentence as an equation about those variables, then solve by trying each assumption in turn. 3-person version: A says "B tells the truth", B says "C lies", C says "A lies"; if exactly one person tells the truth, the answer is that C tells the truth.', src: '7cd943d9eadb' },
  'amc10-0554': { front: 'What should you check first in a self-referential statement problem?', back: 'Assume it is true and assume it is false, and see whether each is self-consistent. For "this sentence is false" neither assumption is self-consistent, so it is not a proposition with a truth value. Do not judge by feel.', src: '2bbf89c3da76' },
  'amc10-0555': { front: 'How do you confirm that the answer is unique in an information-deduction problem?', back: 'List all the initial possibilities, filter them one by one with the conditions, and confirm at the end that only one remains — rather than stopping as soon as you find one that fits.', src: '198335b394f4' },
  'amc10-0556': { front: 'What is the structure of a direct proof?', back: 'Start from the givens and derive the conclusion step by step using definitions and already proved theorems. Example: the sum of two even numbers is even — just write 2m+2n=2(m+n).', src: 'c219d9078601' },
  'amc10-0557': { front: 'How does a proof by cases guarantee completeness?', back: 'The cases are mutually exclusive and their union is the whole set, with boundary cases confirmed separately. To prove |x|+x≥0, split into x≥0 and x<0, which covers everything exactly and without overlap.', src: '92aaeacd9680' },
  'amc10-0558': { front: 'How does an exchange argument show that a greedy choice is no worse?', back: 'Take any optimal solution, replace its first choice that differs from the greedy one, and prove that the result is still feasible and the objective value does not get worse; hence an optimal solution starting with the greedy choice exists. Pushing this forward step by step yields the greedy optimum.', src: 'e8f7999efb92' },
  'amc10-0559': { front: 'What are the two steps of induction?', back: '①Verify the base case; ②assume case n holds and derive case n+1. To prove 1+2+…+n=n(n+1)/2, n=1 holds, and then n(n+1)/2+(n+1)=(n+1)(n+2)/2 completes the step.', src: '31a4f2fbeba8' },
  'amc10-0560': { front: '"I can recite the formula but cannot get started" — which kind of card should you add?', back: 'Add recognition cards of the form "problem structure → first-choice method", rather than copying the formula out again. The front of a recognition card must give a concrete situation with numbers, and the back gives the action and the result.', src: 'e45448654268' },
  'amc10-0561': { front: 'How does each knowledge card connect to doing problems?', back: 'Bind it to at least one worked example or a real exam problem number, and record the date you first got it right on your own. A card with no problem-number anchor makes it hard to judge whether you can really use it.', src: 'd71596c050e5' },
  'amc10-0562': { front: 'How complete must your answer be for a card to pass?', back: 'Not just the formula: you must also state the applicability conditions, the boundary/equality case, and one typical trigger word. For stars and bars, for example, you must state clearly that the items are identical and the boxes are distinct.', src: '44a0858d7f5e' },
  'amc10-0563': { front: 'How do you keep cards from getting too big?', back: 'One card asks only one independently checkable question; split definitions, formulas, applicability conditions, and traps into several cards when necessary — better one card too many than vagueness.', src: '73edf5df7b5d' },
  'amc10-0564': { front: 'How do you avoid being able to recall only in the forward direction?', back: 'For the same key point, make cards in both directions, "name → formula" and "structure → method". Someone who can recall only forward gets stuck on problems that use it in reverse.', src: '8cdf17bd9232' },
  'amc10-0336': { front: 'What is the volume of a cylinder?', back: 'πr²h.', src: '9621b1958d43' },
  'amc10-0337': { front: 'What is the lateral surface area of a cylinder?', back: '2πrh.', src: 'ef1eda2fd989' },
  'amc10-0338': { front: 'What is the volume of a cone?', back: 'πr²h/3.', src: '981731e3064d' },
  'amc10-0339': { front: 'What is the lateral surface area of a cone?', back: 'πrℓ, where ℓ is the slant height.', src: '87e564b409ed' },
  'amc10-0340': { front: 'What is the volume of a sphere?', back: '4πr³/3.', src: 'c15f8324480d' },
  'amc10-0341': { front: 'What is the surface area of a sphere?', back: '4πr².', src: '2581941a1f9b' },
  'amc10-0342': { front: 'What is the key equation in a volume-conservation problem?', back: 'The total volume of the material/liquid is equal before and after the change; watch out for overflow and gaps.', src: '0120fb6d0d20' },
  'amc10-0343': { front: 'How is the volume ratio of similar solids obtained from the length ratio?', back: 'The cube of the length ratio.', src: 'b10f09d204d8' },
  'amc10-0344': { front: 'What is the space diagonal of a rectangular box?', back: '√(l²+w²+h²).', src: 'a2e719475616' },
  'amc10-0345': { front: 'What is Euler’s polyhedron formula?', back: 'For a convex polyhedron, V-E+F=2.', src: 'c912a81be8b4' },
  'amc10-0346': { front: 'What is the method of double counting the edges of a polyhedron?', back: 'The sum of the numbers of edges of all faces equals 2E; the sum of the degrees of all vertices also equals 2E.', src: '7dccb5cfd323' },
  'amc10-0347': { front: 'What is the first step in a cross-section problem?', back: 'Identify which edges/faces the cross-section intersects, then use similarity or coordinates to find the side lengths.', src: 'd1f9ee282b63' },
  'amc10-0348': { front: 'How do you handle the shortest path on a net?', back: 'Unfold the adjacent faces, turning the broken path across the faces into a straight line in the plane.', src: 'aa63331c781d' },
  'amc10-0349': { front: 'What must you watch out for in a container liquid-level problem?', back: 'When the shape of the container changes the cross-sectional area may not be constant, so you cannot always use proportionality of the heights.', src: 'f7668368985d' },
  'amc10-0350': { front: 'Does the AMC 10 require trigonometry?', back: 'The official scope excludes trigonometry; handle special angles with special triangles and geometric relations.', src: '2067bfe7341e' },
  'amc10-0351': { front: 'What is the slope-intercept form of a line?', back: 'y=mx+b, valid for non-vertical lines.', src: '05aa92d911e1' },
  'amc10-0352': { front: 'What is the point-slope form through the point (x₁,y₁) with slope m?', back: 'y-y₁=m(x-x₁).', src: '0f580992d22d' },
  'amc10-0353': { front: 'What are the equations of a vertical line and a horizontal line?', back: 'x=c and y=c.', src: '85c7c1c99282' },
  'amc10-0354': { front: 'What is the standard equation of a circle?', back: '(x-h)²+(y-k)²=r², with centre (h,k) and radius r.', src: 'e7c569585978' },
  'amc10-0355': { front: 'How do you find the distance from a point to a horizontal or vertical line?', back: 'The absolute value of the coordinate difference.', src: 'e541bc3e8f94' },
  'amc10-0356': { front: 'What is the distance from a point to the general line Ax+By+C=0?', back: '|Ax₀+By₀+C|/√(A²+B²).', src: '9ed35a6a362e' },
  'amc10-0357': { front: 'What does coordinate addition of two vectors express?', back: 'Displacements add coordinate by coordinate; it can handle successive translations and the endpoint of a path.', src: '5e51d95969b5' },
  'amc10-0358': { front: 'What is the coordinate test for two vectors being perpendicular?', back: 'The dot product u₁v₁+u₂v₂=0.', src: '4bb19c218d87' },
  'amc10-0359': { front: 'What is Pick’s theorem?', back: 'For a simple lattice polygon the area is A=I+B/2-1, where I is the number of interior lattice points and B is the number of boundary lattice points.', src: 'dd59fd648ca7' },
  'amc10-0360': { front: 'When both ends of a segment are lattice points, what is the number of gaps between the boundary lattice points?', back: 'gcd(|Δx|,|Δy|); including both ends, the number of lattice points is that +1.', src: 'be24ec8f91c7' },
  'amc10-0361': { front: 'What are the common tests for four points being concyclic?', back: 'Opposite angles are supplementary; or equal angles subtending the same chord with the two points on the same side of the chord (on opposite sides the two angles are supplementary).', src: '46475798eb04' },
  'amc10-0362': { front: 'What is the tangent-chord theorem?', back: 'The angle formed by a tangent and a chord equals the inscribed angle that the chord subtends on the other side of the circle.', src: 'a8e4671396d4' },
  'amc10-0363': { front: 'What is Ptolemy’s theorem?', back: 'For a cyclic quadrilateral, the product of the two diagonals equals the sum of the products of the two pairs of opposite sides.', src: '293c137ea7c5' },
  'amc10-0364': { front: 'What is the relation between the common chord of two circles and the line joining their centres?', back: 'The common chord is perpendicular to the line joining the centres of the two circles.', src: '84af864abe2f' },
  'amc10-0365': { front: 'What is the idea of the radical axis?', back: 'The points with equal power with respect to two circles form a line, which contains the line of the common chord through the intersection points of the two circles.', src: '965419795490' },
  'amc10-0366': { front: 'What is Ceva’s theorem used for?', back: 'Deciding that three cevians are concurrent: the product of the directed length ratios = 1 (including the case where the three lines are parallel); when using undirected length ratios you must restrict to the case where all three points lie on the three sides.', src: '6fc0ba97617c' },
  'amc10-0367': { front: 'What is Menelaus’ theorem used for?', back: 'Deciding that the three intersection points of one line with the three sides of a triangle or their extensions are collinear; directed lengths must be used with care.', src: '785bef8f64a4' },
  'amc10-0368': { front: 'Why does a median bisect the area of a triangle?', back: 'The two sub-triangles share the same altitude and have equal bases.', src: 'c28977ff1fd3' },
  'amc10-0369': { front: 'What is the priority rule for tracking area ratios?', back: 'First look for equal altitudes and equal bases, then for the square of the similarity ratio, and only then compute the actual lengths.', src: '5eaa80258f24' },
  'amc10-0370': { front: 'What is the angle condition for regular polygons to tile around a vertex?', back: 'The sum of the interior angles meeting at that point must be 360°.', src: 'be3be1bf72af' },
  'amc10-0371': { front: 'What is the composition of two reflections in parallel lines?', back: 'A translation along the perpendicular direction, by 2 times the distance between the two lines.', src: '66f729091d5d' },
  'amc10-0372': { front: 'What is the composition of two reflections in intersecting lines?', back: 'A rotation about the intersection point, through 2 times the angle between the two lines.', src: '9b557deb45e9' },
  'amc10-0373': { front: 'Why is the composition of transformations usually not commutative?', back: 'Changing the order changes the intermediate position; you should track a general point to check.', src: 'a0a339c7ac76' },
  'amc10-0374': { front: 'How do you avoid double counting in the surface area of a composite solid?', back: 'Add the areas of all the exposed faces; glued faces do not count, and usually you must subtract once from the surface area of each of the two solids.', src: 'a81e063fffdf' },
  'amc10-0375': { front: 'How do you reduce the dimension of a tangency problem for an axisymmetric cone/cylinder?', back: 'Take the cross-section through the axis, turning it into a problem of triangles, rectangles and an incircle.', src: '233bde84f070' },
  'amc10-0376': { front: 'How are the liquid level and the volume related in similar containers?', back: 'If the cross-sections stay similar when measured from the apex, the volume ratio equals the cube of the corresponding height ratio.', src: '5100a4f58c6c' },
  'amc10-0377': { front: 'What property does a cross-section parallel to the base of a pyramid have?', back: 'The cross-section is similar to the base, and the length ratio equals the ratio of the heights from the apex to the cross-section.', src: 'bb4c820b1051' },
  'amc10-0378': { front: 'What does distance mean in the graph of a polyhedron?', back: 'Treating the vertices and edges as a graph, the distance is the fewest number of edges to walk along the edges, not the straight-line distance in space.', src: '6597776eaebe' },
  'amc10-0379': { front: 'Can you still use the area ratio directly when the density is not uniform?', back: 'No; use the area ratio only when the point is chosen uniformly with respect to area, and for a partition you often need density × area as the weight.', src: 'd0d2d8862f6b' },
};
/** 按当前语言本地化一张卡：en 走覆盖层，其它语言（或缺失条目）回退中文基底。 */
export function localizeFlashcard(card: Flashcard, locale: Locale): Flashcard {
  if (locale !== 'en') return card;
  const overlay = FLASHCARD_EN[card.id] ?? DRILL_EN[card.id] ?? SCENARIO_EN[card.id];
  return overlay ? { ...card, front: overlay.front, back: overlay.back } : card;
}
